INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2706', 'spa', 'Algo prescrito: estatuto, ordenanza o decreto; porción asignada o cuota; límite o frontera fijada.', 'חֹק es uno de los términos jurídicos centrales de la Biblia hebrea, derivado de la raíz חקק («grabar, inscribir, decretar»). En su núcleo reside la idea de algo fijo, prescrito, grabado en piedra, ya sea una ley divina, una ración alimentaria asignada o el límite que Dios puso al mar. Su uso más frecuente, que abarca la gran mayoría de sus 128 ocurrencias, lo empareja con מִשְׁפָּט («juicio») como binomio estándar para la instrucción integral de Dios a Israel: «estatutos y ordenanzas» (Éx 15:25; Lv 26:46). Pero bajo la abstracción legal, la palabra conserva una concreción material fascinante: la «porción prescrita» aparece cuando José asegura raciones de grano para los sacerdotes egipcios (Gn 47:22) y cuando Agur pide su pan diario, «dame mi porción asignada» (Pr 30:8). Un tercer sentido —límite cósmico— emerge en la poesía sapiencial, donde Dios pone un חֹק al mar (Pr 8:29; Job 26:10), decretando fronteras que las aguas no pueden traspasar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2707', 'spa', 'Grabar, tallar; esculpir figuras en una superficie; marcar un límite o frontera', 'Verbo hebreo poco frecuente (emparentado con חָקַק, ''inscribir'') que aparece solo en las conjugaciones Pual y Hitpael. En su forma de participio Pual describe imágenes talladas o grabadas en las puertas del templo (1 R 6:35) y en los muros de visiones proféticas de idolatría (Ez 8:10; 23:14). En Job 13:27, el Hitpael transmite la idea de que Dios ''inscribe un límite'' alrededor de las plantas de los pies de Job. Su campo semántico abarca desde el grabado físico hasta la demarcación metafórica de fronteras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2708', 'spa', 'Estatuto u ordenanza prescrita; regulación vinculante de Dios o de un gobernante, de carácter frecuentemente permanente y ritual.', 'חֻקָּה es la forma femenina de חֹק y designa un estatuto prescrito u ordenanza promulgada, empleada de manera abrumadora para leyes divinas de carácter permanente y ritual. La frase חֻקַּת עוֹלָם («estatuto perpetuo») se repite a lo largo de Éxodo, Levítico y Números para las regulaciones de la Pascua, los deberes sacerdotales y los ritos del Día de la Expiación (Éx 12:14; Lv 16:29). Sin embargo, חֻקָּה también designa las ordenanzas fijas de la naturaleza: las estaciones señaladas (Jer 5:24) y los decretos cósmicos que gobiernan cielo y tierra (Jer 31:35; 33:25). Español estatuto, francés statut y alemán Satzung la vierten sistemáticamente como ley formal promulgada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2710', 'spa', 'Grabar, inscribir o cincelar; por extensión, decretar o promulgar leyes; como sustantivo, gobernante, legislador o el cetro que simboliza autoridad. U', 'Grabar, inscribir o cincelar; por extensión, decretar o promulgar leyes; como sustantivo, gobernante, legislador o el cetro que simboliza autoridad. Un verbo ricamente estratificado cuya imagen central es el acto de cortar marcas en una superficie dura: piedra, metal o tablilla. De este acto físico de grabar fluye la metáfora de inscribir la ley: quien graba decretos en piedra se convierte en legislador, y el bastón que sostiene se convierte en cetro de autoridad. En Génesis 49:10 Jacob profetiza que el cetro (מְחֹקֵק) no se apartará de Judá, mientras en Isaías 49:16 Dios declara ''te he grabado en las palmas de mis manos'', el mismo verbo pasando de la autoridad política a la ternura íntima.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2713', 'spa', 'Escudriñar, investigar, examinar o sondear; en Nifal, ser sondeable o investigable.', 'Escudriñar, investigar, examinar o sondear; en Nifal, ser sondeable o investigable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2714', 'spa', 'Escudriñamiento, investigación — el acto de indagar profundamente en lo oculto, inescrutable o inalcanzable', 'El sustantivo חֵקֶר (cheqer) designa el proceso o resultado de una investigación profunda: un escudriñamiento exhaustivo de lo que está oculto. Aparece con mayor frecuencia en la literatura sapiencial y poética, donde subraya los límites del conocimiento humano ante el misterio divino. Job declara que las maravillas de Dios son ''inescrutables'' (Job 5:9; 9:10), y el salmista afirma que la grandeza de Dios es ''inescrutable'' (Sal 145:3). En Jueces 5:15-16, Débora pregunta por qué Rubén se demoraba entre ''búsquedas del corazón'' — una deliberación introspectiva sobre si unirse a la batalla. Proverbios emplea el término para las profundidades insondables del corazón de un rey (Pr 25:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2715', 'spa', 'Nobles, hombres principales — la clase patricial gobernante, especialmente de la Judá postexílica junto a los oficiales.', 'Un término tardío para la aristocracia hereditaria que aparece casi exclusivamente en Nehemías, donde designa a los ''nobles'' que, junto con los סְגָנִים (''oficiales''), constituían la élite gobernante de la Jerusalén postexílica. Nehemías se apoya en ellos y a la vez los reprende: ayudan a reconstruir los muros (Neh 4:14, 19), pero también se emparentan con la familia de Tobías (6:17) y explotan a los pobres (5:7). Usos anteriores sitúan a los nobles en la ciudad de Nabot (1 R 21:8, 11), en la corte judía de Jeremías (Jer 27:20; 39:6) y en el liderazgo condenado de Edom (Is 34:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2717a', 'spa', 'Secarse o estar seco; en el Hifil, hacer secar; dicho de aguas, tierras y vegetación. חָרֵב es la palabra de la Biblia hebrea para el avance inexorabl', 'Secarse o estar seco; en el Hifil, hacer secar; dicho de aguas, tierras y vegetación. חָרֵב es la palabra de la Biblia hebrea para el avance inexorable de la sequedad: aguas que retroceden, lechos de ríos que se agrietan, vegetación que se marchita bajo juicio divino o proceso natural. Su primera aparición es cósmica: después del diluvio, la superficie de la tierra ''se secó'' (Gn 8:13). El salmista celebra a Dios reprendiendo al Mar Rojo para que ''se secara'' (Sal 106:9), e Isaías advierte que el Nilo ''se secará y quedará árido'' (Is 19:5-6). En el Hifil, el agente, casi siempre Dios, seca activamente las aguas: ''yo sequé el mar'' (Is 50:2). Ya sea describiendo evaporación natural o intervención soberana, חָרֵב evoca consistentemente el poder de Dios sobre el agua y la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2717b', 'spa', 'Estar desolado o en ruinas; en Hifil, asolar o destruir; como participio, un destructor o devastador.', 'Estar desolado o en ruinas; en Hifil, asolar o destruir; como participio, un destructor o devastador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2717c', 'spa', 'Atacar, combatir, abatir; hacer la guerra contra (verbo raro de influencia aramea, distinto de חָרַב ''secarse'')', 'Verbo poco frecuente (חָרַב III), distinto del común חָרַב que significa ''estar seco/desolado'', con cognados en árabe (ḥaraba, ''saquear, guerrear'') y en siríaco (''golpear, matar''). Aparece en contextos militares: Dios ordena atacar Merataim y Pecod (Jer 50:21, 27) y se informa que los reyes moabitas ''lucharon entre sí'' y se abatieron mutuamente (2 R 3:23). El sentido bélico se confirma por verbos paralelos como הַחֲרֵם (''destruir por completo'') y por la construcción de combate recíproco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2719', 'spa', 'Espada, arma principal de guerra y juicio divino; raramente «cuchillos» (pedernales) o «ruinas» (por confusión homofónica).', 'חֶרֶב es la palabra bélica por excelencia de la Biblia hebrea, con más de 400 apariciones para designar la espada en todas las dimensiones de la experiencia israelita, desde el mundo de Caín hasta las visiones apocalípticas de los profetas. Nombra la hoja literal al costado del guerrero (1 S 21:9), el instrumento de ejecución judicial y la temible «espada de YHWH» que recorre los oráculos proféticos de juicio (Jer 12:12; Ez 21). Dos sentidos marginales emergen de los datos: en Josué 5:2-3 las glosas multilingües como «cuchillos de» apuntan a cuchillos de pedernal para la circuncisión, no a espadas de guerra. Una ocurrencia aislada en 2 Crónicas 34:6 parece vinculada al homófono חָרְבוֹת que significa «ruinas».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2720b', 'spa', 'Arruinado, desolado, devastado; describe ciudades o lugares que han sido destruidos y dejados sin habitantes.', 'El adjetivo charev (II) describe lugares — especialmente ciudades y edificaciones — que se encuentran en estado de ruina y desolación, desprovistos de habitantes. Se distingue del verbo relacionado charav (''estar seco, desolado'') por funcionar como descriptor fijo de estados posteriores a la destrucción. Nehemías lo usa dos veces respecto a las puertas quemadas y los muros derruidos de Jerusalén (Neh 2:3, 17). Ezequiel lo emplea en oráculos de restauración donde las ciudades antes desoladas serán reconstruidas y habitadas (Ez 36:35, 38). Hageo lo aplica incisivamente al templo que yace en ruinas mientras el pueblo vive en casas artesonadas (Hag 1:4, 9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2721a', 'spa', 'Sequía, calor abrasador — aridez extrema o calor sofocante que marchita la vegetación y amenaza la vida', 'El sustantivo חֹרֶב (choreb) se refiere a la fuerza desecante de la sequía o el calor extremo, lo opuesto a la humedad y el rocío. Jacob lo evoca vívidamente al relatar sus años con Labán: ''de día me consumía el calor, y de noche la helada'' (Gn 31:40). Gedeón lo utiliza como prueba: el vellón debía permanecer seco mientras el suelo estaba mojado (Jue 6:37, 39). Los profetas lo emplean como figura del juicio divino: Jeremías invoca la sequía sobre las aguas de Babilonia (Jer 50:38), Hageo la vincula con la infidelidad al pacto (Hag 1:11) y Sofonías la asocia con la desolación (Sof 2:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2721b', 'spa', 'Desolación, devastación, ruina; estado de haber sido asolado (distinto de חֹרֶב ''sequedad'' y חֶרֶב ''espada'')', 'Sustantivo que significa ''desolación'' o ''ruina'', estrechamente emparentado con el verbo חָרַב (''estar desolado'') pero distinto de חֹרֶב I (''sequedad, sequía'') y de חֶרֶב (''espada''). Describe la devastación absoluta de ciudades y territorios: Isaías 61:4 habla de reconstruir ''ciudades de desolación'' (עָרֵי חֹרֶב), Jeremías 49:13 profetiza que Bosra quedará hecha un desierto, y Ezequiel 29:10 declara a Egipto ''ruinas de desolación''. Su emparejamiento con שְׁמָמוֹת (''asolamientos'') y חָרְבוֹת (''ruinas'') refuerza su campo semántico de destrucción total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2722', 'spa', 'Horeb: el monte de Dios en el desierto, sinónimo de Sinaí en la tradición deuteronómica', 'Horeb: el monte de Dios en el desierto, sinónimo de Sinaí en la tradición deuteronómica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2723', 'spa', 'Ruina, desolación; los escombros físicos o el estado abstracto de un lugar destruido', 'Ruina, desolación; los escombros físicos o el estado abstracto de un lugar destruido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2724', 'spa', 'Tierra seca o suelo firme, especialmente el revelado por el retiro milagroso de las aguas en actos divinos de liberación.', 'Sustantivo femenino que designa la tierra firme y seca, o el suelo que ha quedado expuesto al retirarse las aguas. Su uso más memorable aparece en los cruces milagrosos: cuando el Jordán se partió ante Israel (Jos 3:17) y cuando el mar se abrió ante Moisés (Éx 14:21), el suelo descubierto recibe el nombre de חֲרָבָה. También figura en Gn 7:22, señalando la tierra seca de la cual fue barrido todo aliento de vida por el diluvio. La palabra evoca con fuerza la imagen de un lecho desnudo donde antes había agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2729', 'spa', 'Temblar, estremecerse de temor o reverencia; en el Hifil, aterrorizar o causar temblor', 'Temblar, estremecerse de temor o reverencia; en el Hifil, aterrorizar o causar temblor');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2730', 'spa', 'Tembloroso, temeroso; el que tiembla de terror en la batalla o de reverente temor ante la palabra de Dios.', 'El adjetivo verbal חָרֵד describe a una persona en estado de temblor, ya sea por terror en el campo de batalla o por reverente temor ante Dios. La famosa reducción del ejército de Gedeón comienza enviando a casa a todo חָרֵד, a todo el que temblaba de miedo (Jue 7:3). El corazón de Elí tiembla por el arca de Dios (1 Sam 4:13). Pero en Esdras e Isaías, la palabra adquiere un sentido profundamente positivo: los que ''tiemblan ante la palabra de Dios'' son el remanente fiel, los devotos que toman en serio la revelación divina (Esd 9:4; 10:3; Isa 66:2, 5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2731', 'spa', 'Temblor, terror o pavor angustioso; estremecimiento que se apodera del cuerpo al ser vencido por el miedo o el pánico divino.', 'Sustantivo femenino que capta la experiencia visceral y física de temblar bajo el dominio del miedo o el asombro. Cuando Isaac descubrió el engaño de Jacob, el texto dice que ''se estremeció con grandísimo estremecimiento'' (Gn 27:33), una construcción cognada que subraya la pérdida total de compostura. En 1 Samuel 14:15 el pánico en el campamento filisteo se llama ''temblor de Dios'', un terror sobrenatural que hizo temblar la tierra misma. La palabra puede matizarse como inquietud o preocupación, como cuando Eliseo pregunta a la sunamita si necesita que interceda por ella (2 R 4:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2734', 'spa', 'חָרָה es el verbo principal de la Biblia para describir cómo se enciende la ira, y aparece abrumadoramente en la expresión חָרָה אַף — literalmente ''s', 'חָרָה es el verbo principal de la Biblia para describir cómo se enciende la ira, y aparece abrumadoramente en la expresión חָרָה אַף — literalmente ''su nariz ardió'', ya que el hebreo sitúa la ira en la nariz que se dilata. La imagen es visceral: la ira como fuego que se enciende en el rostro. La ira de Dios ''arde'' contra la rebeldía de Israel (Nm 11:1; Éx 22:24), y la ira humana ''se enciende'' en momentos de celos, insulto o injusticia — desde la furia homicida de Caín (Gn 4:5) hasta la indignación de David ante la parábola de Natán (2 S 12:5). La evidencia multilingüe revela cuán profundamente encarnada está esta metáfora: el español ''se encendió'', el alemán ''entbrannte'' y el francés ''brûla'' preservan la imaginería del fuego. El Hitpael reflexivo en el Salmo 37 — ''no te impacientes'' — dirige el ardor hacia adentro, advirtiendo contra la envidia que consume.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2738', 'spa', 'ortigas, maleza, vegetación silvestre de lugares abandonados', 'Tipo de maleza o planta silvestre que crece en lugares descuidados o devastados. La identificación botánica exacta es incierta; se han propuesto ortigas, garbanzos y diversas plantas espinosas. El término aparece en contextos de desolación: viñedos abandonados, tierras arrasadas y refugios de marginados. La planta representa el fracaso agrícola, el triunfo de lo silvestre sobre lo cultivado y la reversión de tierras productivas en páramos. Sea que designe una especie concreta o maleza en general, simboliza abandono y ruina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2740', 'spa', 'Ardor de ira, furor encendido; el calor abrasador de la furia divina, usado casi siempre de la ira de Dios', 'Ardor de ira, furor encendido; el calor abrasador de la furia divina, usado casi siempre de la ira de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2742a', 'spa', 'Agudo, afilado (de instrumentos de trilla); en sentido figurado: diligente, laborioso (de personas en Proverbios).', 'Adjetivo versátil cuya raíz evoca la idea de filo o corte. En contextos agrícolas se refiere al trillo, una pesada plataforma de madera tachonada con piedras o dientes de hierro que se arrastraba sobre el grano para separar la cáscara (Is 28:27; Am 1:3). La escalofriante imagen de Amós, donde Damasco trilla a Galaad ''con trillos de hierro'', captura la fuerza brutal de este instrumento. En Proverbios, la misma raíz gira hacia el carácter humano: la persona ''afilada'' o perspicaz se convierte en el diligente cuyas manos producen riqueza, contrastado sistemáticamente con el perezoso y el engañoso (Pr 10:4; 13:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2742d', 'spa', 'Oro, oro fino; sinónimo poético de זָהָב usado en la literatura sapiencial para expresar el valor material supremo.', 'El sustantivo חָרוּץ (V) es un término poético para el oro, distinto del común זָהָב y del arameo דְּהַב. Aparece exclusivamente en contextos poéticos elevados — literatura sapiencial y Salmos — siempre emparejado con plata (כֶּסֶף) para enmarcar comparaciones de valor supremo. Proverbios declara repetidamente que la sabiduría supera al חָרוּץ (Prov 3:14; 8:10, 19; 16:16). El salmista describe alas de paloma que relucen con el amarillo verdoso del חָרוּץ (Sal 68:14), y Zacarías describe a Tiro amontonando oro como polvo (Zac 9:3). El cognado fenicio confirma el significado de metal precioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2748', 'spa', 'Mago, sacerdote-adivino — practicante erudito de magia ritual en las cortes de Egipto y Babilonia', 'El sustantivo חַרְטֹם (chartom) designa una clase de sacerdotes-magos eruditos vinculados a las cortes reales de Egipto y Babilonia. En Egipto, el faraón convoca a sus chartummim para interpretar sus sueños (Gn 41:8, 24) y para replicar las señales de Moisés (Éx 7:11, 22; 8:3). Logran imitar las dos primeras plagas pero fracasan con los mosquitos, admitiendo ''esto es el dedo de Dios'' (Éx 8:14-15), y ellos mismos son afligidos con úlceras (Éx 9:11). En Daniel, el mismo término reaparece para los magos de la corte babilónica, a quienes Daniel supera diez veces (Dn 1:20; 2:2). La palabra probablemente deriva del egipcio hry-tp (''sacerdote lector principal'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2749', 'spa', 'mago, sacerdote-adivino; miembro de la clase profesional de practicantes ocultistas en cortes reales', 'El termino חַרְטֹם designa a los magos profesionales y sacerdotes-adivinos que servian en las cortes reales del antiguo Cercano Oriente. En Daniel aparecen como una de varias clases de expertos convocados por los reyes babilonicos para interpretar suenos y misterios, pero fracasan sistematicamente donde Daniel, fortalecido por Dios, tiene exito. La palabra es aramea en su uso danielico y posee un cognado hebreo empleado para los magos egipcios en las narrativas de Jose y el Exodo. El patron multilingue converge en la nocion de especialistas ocultistas cortesanos, no practicantes populares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2750', 'spa', 'Ardor de ira, furor encendido; siempre en la frase constructa חֳרִי אַף (''ardor de la nariz/ira'').', 'El sustantivo masculino חֳרִי significa ''ardor'' o ''calor intenso'' y aparece exclusivamente en la frase constructa fija חֳרִי (הָ)אַף — literalmente ''ardor de la nariz'', es decir, ira feroz o furor encendido. Intensifica la ya vívida imagen hebrea de la ira como calor en la nariz. Moisés se aparta del Faraón en gran חֳרִי אַף (Éx 11:8). Jonatán se levanta de la mesa en חֳרִי אַף por la humillación que su padre infligió a David (1 Sam 20:34). La frase también describe la ira divina (Dt 29:24) y la furia de ejércitos y reyes (2 Cr 25:10; Isa 7:4; Lam 2:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2752', 'spa', 'Horeo; los habitantes trogloditas pre-edomitas de la región montañosa de Seir, desplazados por los descendientes de Esaú.', 'El gentilicio חֹרִי (II) designa a los horeos, el pueblo autóctono de la región montañosa de Seir antes de que los edomitas los desplazaran. El nombre probablemente deriva de חֹר (''cueva''), identificándolos como moradores de cuevas, lo cual concuerda con el terreno de acantilados de arenisca de Edom. Génesis 14:6 los sitúa en sus montañas durante la invasión de los reyes orientales. Génesis 36:20-30 ofrece una genealogía detallada de Seir el horeo y sus descendientes. Deuteronomio 2:12, 22 registra su desplazamiento por los hijos de Esaú como paradigma de cómo Dios asigna territorios a las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2753', 'spa', 'Horeo, miembro del pueblo troglodita predomita de Seir; también nombre propio en la genealogía de Simeón', 'Gentilicio y adjetivo derivado de חֹר (''cueva, cavidad''), que designa a la población autóctona de la región de Seir, conocida por habitar en cuevas antes de la conquista edomita. Génesis 36 identifica a Seir como ''el horeo'' y enumera a los jefes horeos como habitantes originales de la tierra. Deuteronomio 2:12, 22 relata que los hijos de Esaú los despojaron, tal como Israel desposeyó a los cananeos. El nombre aparece también como nombre propio en la tribu de Simeón (Nm 13:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2757', 'spa', 'cortes, rebanadas (de queso); instrumentos cortantes de hierro', 'Término con dos significados distintos. Primero, se refiere a cortes o rebanadas, específicamente de queso en 1 Samuel. Segundo, designa instrumentos cortantes de hierro, usados como herramientas de trabajo o de tortura. El campo semántico se articula en torno al concepto de «cortar», ya sea dividir la leche en rebanadas de queso o fabricar herramientas cortantes de hierro. El uso violento en Samuel y Crónicas puede involucrar trillos (como en Amós 1:3) o instrumentos de tortura, según la interpretación. Ambos significados derivan de la raíz que denota cortar o dividir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2758', 'spa', 'arada, labranza, temporada de arar', 'La actividad agrícola de arar o la temporada destinada a ella. En el calendario agrario del antiguo Israel, la época de la arada marcaba un período crucial para preparar los campos antes de la siembra. El término puede referirse tanto al acto mismo como a la estación en que se realiza. Génesis y Éxodo lo emplean en combinación con la cosecha para indicar el ritmo del año agrícola. Samuel lo usa en una construcción de acusativo cognado («arar su arada») para describir la asignación de trabajo. La palabra arraiga la experiencia de Israel en los ciclos agrícolas y el trabajo estacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2763a', 'spa', 'Uno de los verbos de mayor carga teológica en la Biblia hebrea, enraizado en el concepto del חֵרֶם — la separación irrevocable de personas, ciudades o', 'Uno de los verbos de mayor carga teológica en la Biblia hebrea, enraizado en el concepto del חֵרֶם — la separación irrevocable de personas, ciudades o bienes, ya sea para su destrucción total o para su pertenencia exclusiva a Dios. La Estela de Mesa emplea la misma palabra para dedicar una ciudad conquistada a Quemós, lo que revela la profunda antigüedad de esta práctica en la cultura semítica. En contextos de guerra santa (Dt 2:34; Jos 6:21), exige la aniquilación total como acto de obediencia. Sin embargo, la misma raíz en Levítico 27:28 y Miqueas 4:13 describe la consagración de riquezas al SEÑOR — destrucción y dedicación convergen en la idea única de que lo consagrado a Dios no puede volver al uso común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2764a', 'spa', 'Cosa consagrada, anatema — algo entregado irrevocablemente a Dios, ya sea para destrucción o para uso sagrado', 'Cosa consagrada, anatema — algo entregado irrevocablemente a Dios, ya sea para destrucción o para uso sagrado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2764b', 'spa', 'Red o red barredera para pescar o atrapar presas; distinto del homónimo חֵרֶם que significa ''anatema, consagración al exterminio''.', 'Este es el segundo חֵרֶם: no el temible ''anatema de destrucción'', sino una simple red de pescador o cazador, derivado de la idea de material perforado (cf. árabe mukharram, ''perforado''). Habacuc 1:15-17 pinta al imperio caldeo como un pescador que captura naciones en su red barredera y luego adora a la red misma. Ezequiel emplea la imagen en ambas direcciones: las ruinas de Tiro se convierten en lugar para tender redes (Ez 26:5, 14), mientras que Dios lanzará su propia red sobre Faraón (Ez 32:3). Eclesiastés 7:26 la usa para la mujer seductora cuyo corazón es ''redes y lazos''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2766', 'spa', 'Harim — nombre propio que significa ''consagrado/dedicado''; familias sacerdotales y laicas en el Judá postexílico', 'El nombre חָרִם (Harim) probablemente deriva de una raíz que significa ''consagrado'' o ''de nariz chata'' (esto último como rasgo físico). Identifica tanto a familias sacerdotales como laicas prominentes en la comunidad postexílica. Una casa sacerdotal de Harim recibió el tercer turno en la organización del servicio del templo de David (1 Cr 24:8) y reaparece en el retorno del exilio (Esd 2:39; Neh 7:42; 12:15). Miembros de esta familia sacerdotal estuvieron entre quienes se habían casado con mujeres extranjeras (Esd 10:21). Una familia laica separada de Harim también regresó de Babilonia (Esd 2:32; Neh 7:35), con miembros igualmente involucrados en la crisis de los matrimonios mixtos (Esd 10:31). Un Harim selló el pacto bajo Nehemías (Neh 10:5, 27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2767', 'spa', 'Horma, ciudad cananea del Neguev renombrada después de que Israel ''consagró al exterminio'' a sus habitantes.', 'Originalmente llamada Sefat, esta ciudad del sur del Neguev fue renombrada Horma, nombre transparentemente derivado de חֵרֶם (''consagrado a destrucción''), después de que Judá y Simeón la conquistaron (Jue 1:17). La etimología popular es central: el topónimo mismo conmemora el acto de guerra santa. Números 14:45 registra una derrota israelita anterior allí, y Números 21:3 narra el voto y la subsiguiente destrucción que dieron a la ciudad su nombre. Asignada a Simeón dentro del territorio de Judá (Jos 15:30; 19:4), reaparece como una de las ciudades a las que David envió botín (1 S 30:30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2768', 'spa', 'Hermón — la imponente cumbre nevada de la cordillera del Antilíbano que marca la frontera norte de Israel.', 'La cumbre sagrada de la cordillera del Antilíbano, el monte Hermón se eleva a casi 2.814 metros y servía como el gran punto de referencia geográfico del límite norte de Israel. Conocido por distintos nombres entre los pueblos vecinos — Sirión para los sidonios y Senir para los amorreos (Dt 3:9) —, sus tres picos podrían explicar el plural ''Hermones'' del Salmo 42:6. Su perpetua capa de nieve alimentaba las fuentes del Jordán y lo convertía en símbolo de frescura y bendición divina (Sal 133:3). La raíz hebrea se relaciona con la idea de consagración o espacio dedicado, evocando sus antiguas asociaciones sagradas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2771a', 'spa', 'Harán — ciudad de la Alta Mesopotamia, punto clave en las migraciones patriarcales', 'El topónimo חָרָן (Harán) designa una importante ciudad antigua de la Alta Mesopotamia, situada en el sureste de la actual Turquía, cerca de la frontera siria. Fue el lugar donde Taré se estableció tras salir de Ur de los Caldeos, antes de que Abraham partiera hacia Canaán (Gn 11:31-32; 12:4-5). Jacob huyó allí hacia su tío Labán (Gn 27:43; 28:10; 29:4), y la ciudad siguió asociada a las raíces arameas de la familia patriarcal. Los textos asirios confirman a Harán (Harranu) como un importante centro comercial y religioso dedicado al dios lunar Sin. En contextos proféticos, los asirios citan su conquista como prueba de su poder (2 R 19:12; Is 37:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2772', 'spa', 'el horonita: gentilicio de Sanbalat, opositor de Nehemías', 'Designación geográfica que identifica a Sanbalat como «el horonita», es decir, oriundo de Bet-horón o una localidad relacionada. Sanbalat el horonita fue un opositor clave de los esfuerzos de reconstrucción de Nehemías en Jerusalén, quien buscaba constantemente socavar el proyecto de restauración. La designación aparece exclusivamente en Nehemías, siempre con artículo, distinguiendo a Sanbalat por su lugar de origen. Bet-horón constaba de una ciudad alta y otra baja en Efraín, lo que sitúa a Sanbalat como un opositor samaritano o norteño de la restauración judía. El epíteto se convirtió en su marca identificativa a lo largo de las memorias de Nehemías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2773', 'spa', 'Horonaim (''dos cavidades''), ciudad moabita mencionada en oráculos proféticos de juicio contra Moab', 'Topónimo en forma dual que probablemente significa ''dos cavidades'' o ''dos ciudades-cueva'', emparentado con חֹר (''cueva'') y posiblemente con Bet-horón. Designa una ciudad de Moab que aparece de manera destacada en oráculos proféticos de juicio. Isaías 15:5 y Jeremías 48:3, 5, 34 mencionan Horonaim en contextos de devastación moabita, con gritos de angustia que ascienden o descienden por ''el camino de Horonaim'' o ''la bajada de Horonaim''. La Estela de Mesa (líneas 31-32) también registra el sitio como Horonayín.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2775a', 'spa', 'sol; o topónimo Heres', 'Designa el sol como cuerpo celeste o bien un lugar geográfico llamado Heres. En el discurso poético de Job, Dios ordena al sol que no salga. En Jueces, puede referirse a un sitio denominado Heres o a la «subida del sol». Esta forma aparece raras veces y se distingue del vocablo hebreo habitual para sol por la epéntesis de he. Las cuestiones textuales e interpretativas han generado debate entre los eruditos sobre si ciertas ocurrencias se refieren al astro o a nombres de lugares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2778a', 'spa', 'Afrentar, insultar o desafiar; lanzar injurias o retos despectivos, especialmente contra Dios o su pueblo', 'Afrentar, insultar o desafiar; lanzar injurias o retos despectivos, especialmente contra Dios o su pueblo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2779', 'spa', 'Sustantivo que significa ''invierno, estación fría/lluviosa''; también ''otoño, tiempo de cosecha'' y, por extensión, ''plenitud de la vida''', 'Este sustantivo designa la parte más fría del año agrícola, abarcando lo que podríamos llamar desde el otoño tardío hasta el invierno. En Génesis 8:22 se empareja con קַיִץ (''verano'') en la promesa del pacto divino de que las estaciones nunca cesarán. Describe estructuras físicas asociadas con el clima frío, como la ''casa de invierno'' de Amós 3:15 y la habitación donde Joacim se sienta junto al fuego en el noveno mes (Jeremías 36:22). En un memorable uso figurado, Job recuerda חָרְפִּי (''mi otoño''), la plenitud de su vida cuando la amistad de Dios cobijaba su tienda (Job 29:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2781', 'spa', 'חֶרְפָּה designa el aguijón de la vergüenza pública — la condición de estar expuesto al escarnio, el desprecio o la deshonra social. Aparece en contex', 'חֶרְפָּה designa el aguijón de la vergüenza pública — la condición de estar expuesto al escarnio, el desprecio o la deshonra social. Aparece en contextos que van desde la humillación personal (el ruego de Tamar en 2 S 13:13: ''¿adónde llevaría yo mi afrenta?'') hasta la catástrofe nacional (la ''afrenta de Egipto'' quitada en Gilgal, Jos 5:9). El español ''afrenta'' y el alemán ''Schmach'' portan el peso de un deshonor que cala hasta los huesos. La palabra a veces se agudiza hacia el acto mismo — los insultos lanzados por los enemigos (Sal 69:9; Sof 2:8) — y en Proverbios señala un defecto moral inherente que inevitablemente trae desgracia (Pr 6:33).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2782', 'spa', 'Cortar, afilar o decidir; desde el corte físico y la mutilación hasta decretos autoritativos y acción decisiva', 'חָרַץ transita de lo concreto a lo judicial. En su sentido más físico, describe cortar o mutilar: Levítico 22:22 incluye al animal ''mutilado'' entre los no aptos para el sacrificio. El salto figurativo a ''afilar la lengua'' (Éx 11:7; Jos 10:21) presenta el habla hostil contenida como una hoja afilada: ni un perro afilará su lengua contra Israel. Sin embargo, el uso bíblico predominante es judicial: algo ''determinado'' o ''decretado'', especialmente decisiones divinas irrevocables (Is 10:22-23; 28:22). El cognado asirio haraṣu abarca igualmente ''cavar'' y ''decidir''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2786', 'spa', 'rechinar o crujir los dientes en senal de ira u hostilidad', 'Un verbo vivido que describe el rechinar o crujir de dientes como expresion de furia y hostilidad. En los Salmos, los malvados crujen sus dientes contra el justo (Sal 37:12), y en Job el adversario rechina los dientes contra el que sufre (Job 16:9). Lamentaciones 2:16 capta a los enemigos silbando y crujiendo los dientes en triunfo sobre la caida de Jerusalen. La imagen es visceral e inconfundible: un gesto agresivo y amenazante que comunica rabia intensa dirigida contra otra persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2787', 'spa', 'Estar caliente, quemado o carbonizado; arder, resplandecer; también arder de ira, encender fuego o quedar reseco', 'Un verbo hebreo poético que capta la experiencia del calor intenso en sus múltiples formas. El caldero de bronce de Ezequiel debe ''arder'' vacío sobre las brasas para que su impureza se consuma (Ez 24:11), mientras los habitantes de la tierra ''arden'' bajo el juicio divino (Is 24:6). Los huesos febriles de Job ''arden por la sequía'' (Job 30:30). El verbo penetra en lo emocional en Cantares 1:6, donde los hermanos de la mujer ''ardieron de ira'' contra ella. También describe el encender la contienda (Pr 26:21) y la garganta reseca y ronca de tanto clamar (Sal 69:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2789', 'spa', 'Cerámica, alfarería o tiesto; vasijas de barro o sus fragmentos rotos, que a menudo simbolizan la fragilidad humana ante Dios.', 'Cerámica, alfarería o tiesto; vasijas de barro o sus fragmentos rotos, que a menudo simbolizan la fragilidad humana ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2790a', 'spa', 'Arar, grabar, maquinar; labranza agrícola, maquinación metafórica del mal, pasivo ''ser arado'' e inscripción', 'Arar, grabar, maquinar; labranza agrícola, maquinación metafórica del mal, pasivo ''ser arado'' e inscripción');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2790b', 'spa', 'Callar, guardar silencio; también estar sordo, incapaz o reacio a escuchar', 'Callar, guardar silencio; también estar sordo, incapaz o reacio a escuchar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2793', 'spa', 'Sustantivo que significa ''bosque, altura arbolada, espesura''; zona boscosa elevada usada como refugio o para construcción', 'Este sustantivo designa un área boscosa o altura arbolada, estrechamente relacionado con el acadio hurshu (''tierras altas boscosas''). Aparece de forma memorable en las narrativas de David y Saúl, donde David se esconde en el ''bosque de Zif'' (1 Sam 23:15-19), con el terreno descrito junto a colinas y fortalezas. En 2 Crónicas 27:4, Jotam construye fortificaciones y torres ''en los bosques'', asociando la zona boscosa con la construcción en tierras altas. La palabra evoca no simplemente árboles, sino terreno elevado y densamente arbolado que ofrece refugio natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2795', 'spa', 'Sordo, incapaz de oír; usado literalmente de la sordera física y figuradamente de la imperceptibilidad espiritual.', 'Adjetivo que describe la incapacidad de oír, emparejado habitualmente con ''mudo'' (illem) para expresar la total incapacidad comunicativa (Éx 4:11; Sal 38:14). La literatura profética transforma la sordera física en una poderosa metáfora de la obstinación espiritual de Israel: los ''siervos sordos'' de Isaías tienen oídos pero se niegan a escuchar (Is 42:18-19; 43:8). Sin embargo, los mismos profetas prometen una reversión escatológica: ''los sordos oirán las palabras del libro'' (Is 29:18; 35:5). La llamativa imagen de la ''víbora sorda'' en el Salmo 58:5, que se tapa el oído ante el encantador, añade otra capa metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2796', 'spa', 'Artesano, artífice; obrero diestro en madera, metal, piedra o grabado — desde constructores del templo hasta fabricantes de ídolos', 'Artesano, artífice; obrero diestro en madera, metal, piedra o grabado — desde constructores del templo hasta fabricantes de ídolos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2799', 'spa', 'Trabajo hábil de tallado o grabado en materiales como madera y piedra; artesanía de labrado artístico', 'Se refiere al arte de tallar o a la artesanía especializada, y aparece exclusivamente en las instrucciones para la construcción del Tabernáculo (Éx 31:5; 35:33). Siempre se presenta en estado constructo con un material —madera o piedra—, lo que indica un oficio especializado. El español ''artesanía'' capta bien el sentido de destreza artesanal, mientras que las traducciones al inglés y al francés se inclinan por ''tallado'' o ''corte'', resaltando el acto físico de dar forma a materiales duros bajo la capacitación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2800', 'spa', 'Haroset: ciudad del norte de Israel, sede de Sísara', 'Ciudad del norte de Israel conocida como «Haroset de las naciones» (Haroset-ha-goyim), base militar de Sísara, comandante del ejército del rey Jabín. Se ubicaba probablemente junto al curso inferior del río Cisón, en el valle de Jezreel. La designación «de las naciones» sugiere una población mixta o gentil, coherente con el contexto de resistencia cananea a la expansión israelita. Desde allí Sísara dirigía sus operaciones antes de su derrota a manos de Débora y Barac. Su posición estratégica dominaba los accesos occidentales al valle de Jezreel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2803', 'spa', 'Pensar, calcular, planear o idear; abarca la actividad cognitiva desde el cómputo aritmético hasta la maquinación deliberada y el diseño artístico.', 'חָשַׁב es uno de los verbos cognitivos más ricos del hebreo, cubriendo el arco completo desde la meditación silenciosa hasta la conspiración deliberada. Puede describir a Dios acreditando la fe de Abram como justicia (Gn 15:6), a un artesano ideando diseños artísticos para el tabernáculo (Éx 26:1), o a enemigos tramando el mal (Mi 2:1). El árabe ḥasaba, el etiópico ḥasaba y el arameo חֲשַׁב preservan todos la misma doble acepción de «pensar» y «calcular», reflejando una comprensión semítica de que el cálculo y la contemplación comparten una única actividad raíz de la mente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2805', 'spa', 'Cinto hábilmente tejido del efod sacerdotal, una faja ornamental que ceñía la vestidura a la cintura.', 'Término técnico de la legislación sacerdotal que designa la banda o faja ornamental que sujetaba el efod alrededor de la cintura del sacerdote. Sus ocho apariciones se encuentran exclusivamente en las instrucciones del tabernáculo y sus relatos de cumplimiento en Éxodo y Levítico. Era la pieza que ceñía el efod a la cintura, tejida con el mismo oro, azul, púrpura y escarlata que el efod mismo (Éx 28:8). La raíz חשׁב (''pensar, idear'') sugiere una artesanía de habilidad ingeniosa, y el vocablo alemán ''Binde'' (venda) capta bien la función de sujeción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2808', 'spa', 'cálculo, razonamiento, investigación, maquinación', 'Cálculo mental, razonamiento o maquinación. El término aparece exclusivamente en Eclesiastés, donde se refiere a la investigación intelectual y la búsqueda de comprensión. Qohélet busca sabiduría y «cálculo»: una indagación sistemática del sentido de la vida. La palabra puede tener connotaciones neutras (cálculo racional) o negativas (ardides astutos), según el contexto. Representa el intento humano de comprender y sistematizar la realidad mediante la razón. En la búsqueda de Qohélet, designa los esquemas intelectuales con los que el ser humano intenta dar sentido a la existencia bajo el sol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2809', 'spa', 'Hesbón — la capital amorrea al este del Jordán, ciudad de Sehón, luego territorio de Rubén y Gad', 'Hesbón — la capital amorrea al este del Jordán, ciudad de Sehón, luego territorio de Rubén y Gad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2811', 'spa', 'Hasabías — ''Yahvé ha contado''; nombre levítico portado por músicos, oficiales y funcionarios', 'Nombre teofórico masculino que significa ''Yahvé ha tomado en cuenta'' o ''el SEÑOR ha calculado'', portado por al menos siete individuos distintos, todos ellos levitas o funcionarios del templo. El músico Hasabías sirvió en la vigésimo quinta división del templo bajo David (1 Cr 25:3, 19). Otro Hasabías administró la tribu de Leví bajo David (1 Cr 27:17), y otro más supervisó los asuntos en Hebrón (1 Cr 26:30). En el período postexílico, el nombre prolifera entre quienes regresaron con Esdras (Esd 8:19, 24), sellaron el pacto con Nehemías (Neh 10:11) y sirvieron en el templo restaurado (Neh 11:15, 22; 12:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2814', 'spa', 'Estar en silencio, guardar silencio o quedarse quieto; abarca desde el silencio deliberado hasta acallar a otros y el aquietamiento de fuerzas natural', 'Estar en silencio, guardar silencio o quedarse quieto; abarca desde el silencio deliberado hasta acallar a otros y el aquietamiento de fuerzas naturales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2815', 'spa', 'Hasub, nombre personal llevado por levitas y constructores del muro en el Juda postexilico', 'Un nombre propio hebreo que significa ''considerado'' o ''estimado,'' llevado por varios individuos de la comunidad postexilica. Un Hasub fue jefe levita incluido entre quienes repoblaron Jerusalen (1 Cr 9:14; Neh 11:15). Otros aparecen como constructores que repararon secciones del muro de Jerusalen bajo Nehemias (Neh 3:11, 23) y como signatario de la renovacion del pacto (Neh 10:23). La Septuaginta transcribe el nombre como Asoub/Asouth.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2820', 'spa', 'Retener, refrenar o perdonar; desde contener recursos hasta mostrar misericordia deteniendo la mano', 'Retener, refrenar o perdonar; desde contener recursos hasta mostrar misericordia deteniendo la mano');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2821', 'spa', 'Oscurecerse o volverse oscuro; del cielo, sol o estrellas que pierden luz; de ojos que se nublan; causativamente, traer oscuridad.', 'Oscurecerse o volverse oscuro; del cielo, sol o estrellas que pierden luz; de ojos que se nublan; causativamente, traer oscuridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2822', 'spa', 'El hebreo חֹשֶׁךְ designa la ausencia fundamental de luz, apareciendo por primera vez en el caos primordial de Génesis 1:2 antes de que Dios hable la ', 'El hebreo חֹשֶׁךְ designa la ausencia fundamental de luz, apareciendo por primera vez en el caos primordial de Génesis 1:2 antes de que Dios hable la luz a la existencia. La palabra posee un enorme alcance teológico: la oscuridad tangible de la plaga sobre Egipto (Éx 10:21-22), la densa oscuridad que envolvía el Sinaí en la teofanía (Dt 4:11; 5:22) y la oscuridad metafórica de la ignorancia, el juicio y la muerte (Job 3:4-5; Is 45:7). Cabe destacar que la oscuridad no es simplemente la negación de la luz, sino una presencia activa, casi material — Dios forma la luz y crea la oscuridad (Is 45:7). El español ''oscuridad'' y ''tinieblas'' captan la gravedad del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2825', 'spa', 'Oscuridad, tiniebla; usado para la oscuridad sobrenatural, figurada y asociada a la angustia', 'Un sustantivo poético para la oscuridad que conlleva una resonancia más profunda que la simple ausencia de luz. En Génesis 15:12, una ''gran tiniebla'' cae sobre Abraham durante la ceremonia del pacto — una penumbra sobrenatural y aterradora. Los Salmos lo contraponen a la luz (Sal 139:12) y lo emplean para la ignorancia moral (Sal 82:5). Isaías lo utiliza para la angustia de quienes caminan sin luz (Is 8:22; 50:10). Las voces españolas ''tinieblas'' y ''oscuridad'' captan bien el peso ominoso de este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2828', 'spa', 'Hasum, cabeza de una familia entre los exiliados que regresaron de Babilonia', 'Nombre propio que designa al jefe de una familia prominente entre quienes regresaron del exilio babilónico. Los hijos de חַשֻּׁם sumaban 223 (Esd 2:19) o 328 (Neh 7:22), y algunos de ellos se contaban entre los que habían tomado esposas extranjeras y acordaron despedirlas (Esd 10:33). Hasum también aparece de pie junto a Esdras durante la lectura pública de la Torá (Neh 8:4) y como signatario del pacto (Neh 10:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2830', 'spa', 'metal resplandeciente, ámbar, electro (identificación incierta)', 'Sustancia brillante y misteriosa de identificación incierta, que aparece únicamente en las visiones del trono de Ezequiel. Las interpretaciones tradicionales incluyen ámbar, electro (aleación de oro y plata) u otro material metálico refulgente. El griego lo tradujo como «elektron» y el latín como «electrum». El contexto siempre involucra apariciones divinas, donde la sustancia describe el resplandor que rodea la presencia de Dios. Su brillo y naturaleza enigmática se ajustan a la gloria inefable de las visiones teofánicas. Los estudiosos modernos siguen sin determinar si designa un material concreto o simplemente una luminosidad sobrecogedora, más allá de toda descripción ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2833', 'spa', 'Pectoral — la bolsa sagrada sobre el pecho del sumo sacerdote, engastada con doce piedras preciosas y el Urim y Tumim', 'Pectoral — la bolsa sagrada sobre el pecho del sumo sacerdote, engastada con doce piedras preciosas y el Urim y Tumim');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2834', 'spa', 'Desnudar, dejar al descubierto, exponer; descortezar un árbol; sacar o extraer agua de un recipiente', 'Un verbo de descubrimiento y remoción, empleado en varios dominios vívidos. En los oráculos proféticos de juicio, describe el despojo de vestiduras o la revelación del brazo del SEÑOR (Is 52:10), con frecuencia portando matices de vergüenza o de poder divino manifestado. Joel 1:7 lo aplica concretamente a las langostas que descortezan las higueras. Sorprendentemente, en Isaías 30:14 y Hageo 2:16, la misma raíz pasa a significar sacar agua de una cisterna, mostrando cómo la idea central de extraer o remover se ramifica en acciones físicas distintas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2836a', 'spa', 'Apegarse a, amar, poner el afecto o deseo en alguien o algo.', 'Verbo que expresa un apego emocional profundo y deseo, usado tanto del amor humano como de la elección divina. Cuando el alma de Siquem se apegó a Dina (Gn 34:8), este es el vocablo elegido. De manera más notable, describe por qué Dios eligió a Israel: no por ser numerosos, sino porque ''puso su amor'' en ellos (Dt 7:7; 10:15). En el Salmo 91:14 es la devoción del creyente hacia Dios lo que activa la protección divina. El cognado arameo significa ''atar'', revelando la metáfora física que subyace al sentido emocional. El rango semántico abarca desde el amor hasta el anhelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2836b', 'spa', 'ceñir con molduras, proveer de anillos o filetes (arquitectónico)', 'Verbo especializado en Piel que significa proveer elementos arquitectónicos con molduras, anillos o filetes. Aparece exclusivamente en Éxodo al describir la construcción del tabernáculo, en particular las molduras de plata que conectaban las columnas del atrio. Estas bandas decorativas y estructurales unían las columnas a la vez que les añadían valor estético. El Piel indica acción causativa o intensiva: hacer que algo quede ceñido con molduras o aplicarlas repetidamente. El participio pasivo Pual describe las columnas como «anilladas de plata», mostrando el estado acabado de la obra. Esta terminología técnica refleja la artesanía detallada de la construcción del tabernáculo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2837', 'spa', 'Deseo, deleite; cosa anhelada o placer; usado de los proyectos constructivos de Salomón y del goce personal', 'Denota un deseo profundo o el objeto del deleite de alguien. En los relatos del reinado de Salomón, describe sus ambiciosos proyectos de construcción: todo lo que deseó edificar (1 R 9:1, 19; 2 Cr 8:6). En Isaías 21:4 adquiere un matiz más íntimo: ''el crepúsculo de mi deleite'' se convierte en tiempo de espanto. El español ''deseo'' y el inglés ''desire'' convergen en el significado nuclear, mientras que el pasaje de Isaías muestra que la palabra puede teñirse de un anhelo personal, casi nostálgico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2838', 'spa', 'Molduras o anillos metálicos que ceñían las columnas del atrio del tabernáculo, revestidos de plata u oro.', 'Sustantivo que designa los anillos o bandas metálicas que rodeaban la parte superior de las columnas que sostenían las cortinas del atrio del tabernáculo. Sus ocho apariciones se encuentran exclusivamente en los textos sacerdotales de construcción del tabernáculo en Éxodo, describiendo herrajes revestidos de plata para las columnas del atrio y de oro para las columnas de la entrada. El vocablo deriva de la raíz חשׁק (''atar, sujetar''), y las traducciones convergen en esta función de sujeción: ''anillos'', ''molduras'' y ''bandas'' captan bien su sentido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2843', 'spa', 'Husatita, gentilicio que designa a alguien procedente de Husá en Judá', 'Adjetivo gentilicio que identifica a una persona originaria de la ciudad de Husá, en el territorio de Judá. Siempre se usa con artículo (''el husatita'') como epíteto de guerreros destacados en la compañía de David. Sibecai el husatita mató al gigante filisteo Saf (2 S 21:18; 1 Cr 20:4) y comandaba la octava división mensual (1 Cr 27:11). Mebunai/Ilai el husatita también figura entre los treinta valientes de David (2 S 23:27; 1 Cr 11:29).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2844b', 'spa', 'Quebrantado, destrozado, consternado; describe la derrota física o el terror psicológico', 'Adjetivo que describe a quienes están quebrantados o destrozados, ya sea física o psicológicamente. El término aparece en contextos de derrota militar, colapso político y terror. En el cántico de Ana se usa para el arco quebrado de los guerreros. Isaías lo emplea en la profecía sobre Efraín siendo destrozado como pueblo. Jeremías lo aplica a las fuerzas egipcias derrotadas por Babilonia. La palabra abarca tanto la ruptura física (como un arma destrozada) como la consternación psicológica (como soldados aterrados). Las dificultades textuales en algunos pasajes reflejan la rareza de esta forma particular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2845', 'spa', 'Het — antepasado epónimo de los hititas, hijo de Canaán en la Tabla de las Naciones', 'Nombre propio masculino que identifica al antepasado de los hititas (בְּנֵי חֵת, ''hijos de Het''). En la Tabla de las Naciones, Het figura como hijo de Canaán (Gn 10:15; 1 Cr 1:13). El nombre aparece con mayor frecuencia en la expresión ''hijos de Het'', designando a la población local de Hebrón de quienes Abraham compró la cueva de Macpela como sepultura (Gn 23:3–20; 25:10; 49:32). Las ''hijas de Het'' son las esposas hititas de Esaú, motivo de pesar para Rebeca (Gn 27:46).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2846', 'spa', 'Arrebatar, tomar (especialmente fuego o brasas); por extensión, arrancar violentamente a una persona', 'Describe la acción de arrebatar o tomar, principalmente fuego o brasas ardientes, y por extensión la captura violenta de una persona. En Proverbios 6:27 pregunta si un hombre puede tomar fuego en su seno sin consecuencias, una advertencia vívida contra el adulterio. Proverbios 25:22 lo emplea para amontonar carbones sobre la cabeza del enemigo, e Isaías 30:14 retrata el acto de tomar brasas de un hogar. En el Salmo 52:5 Dios arranca al malvado de la vida misma, extendiendo el sentido al juicio destructivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2850', 'spa', 'Chitti — hitita; adjetivo gentilicio que designa a los miembros del pueblo hitita en Canaán y más allá. El gentilicio Chitti («hitita») identifica a i', 'Chitti — hitita; adjetivo gentilicio que designa a los miembros del pueblo hitita en Canaán y más allá. El gentilicio Chitti («hitita») identifica a individuos o al pueblo colectivo de los hititas, uno de los principales grupos poblacionales que Israel encontró en la tierra de Canaán. Sus 48 apariciones abarcan tres ámbitos de uso distintos. Primero, figura en relatos patriarcales vinculado a individuos concretos: Efrón el hitita, quien vendió la cueva de Macpela a Abraham (Gn 23:10; 25:9), y las esposas hititas de Esaú (Gn 26:34). Segundo, aparece en listas formulaicas de pueblos cananeos que Israel desplazaría (Éx 3:8; Dt 7:1; Jos 3:10). Tercero, identifica a guerreros al servicio de David, muy especialmente a Urías el hitita (2 S 11). La Septuaginta lo traduce sistemáticamente como Χετταῖος.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2851', 'spa', 'Terror o espanto infundido por naciones y guerreros poderosos; usado exclusivamente en los oráculos de Ezequiel contra las naciones.', 'Sustantivo femenino confinado enteramente a Ezequiel, que aparece en el oráculo contra Tiro (Ez 26:17) y en el gran lamento sobre los guerreros caídos en el Seol (Ez 32:23-32). La frase recurrente ''infundieron su terror en la tierra de los vivientes'' resuena como un estribillo fúnebre a lo largo del capítulo 32, aplicada sucesivamente a Asiria, Elam, Mesec-Tubal, Edom y los sidonios. El vocablo capta el espanto que irradiaban estos imperios, un terror ahora silenciado en la tumba. Su restricción a Ezequiel le confiere un sabor de vocabulario profético especializado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2856', 'spa', 'Sellar, fijar un sello o anillo de sellar; cerrar con sello; en pasivo, estar sellado o en estado sellado', 'Sellar, fijar un sello o anillo de sellar; cerrar con sello; en pasivo, estar sellado o en estado sellado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2859a', 'spa', 'Suegro (padre de la esposa); también una vez como suegra (madre de la esposa) en la forma femenina', 'Suegro (padre de la esposa); también una vez como suegra (madre de la esposa) en la forma femenina');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2859b', 'spa', 'Emparentar por matrimonio o hacerse yerno; contraer alianza matrimonial con otra familia, clan o nación (Hitpael de חתן)', 'Un verbo denominativo Hitpael construido sobre la raíz de ''yerno'', que porta dos sentidos relacionales distintos. En un uso, describe a un hombre que se convierte en esposo de una hija, entrando en una casa específica mediante el matrimonio, como cuando David se hizo yerno de Saúl (1 S 18:21-27). En el otro, se amplía para significar forjar una alianza matrimonial entre grupos: emparentar con naciones extranjeras, como se prohíbe en Deuteronomio 7:3 y se lamenta en Esdras 9:14. El español ''emparentar'' capta bien el matiz político-relacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2860', 'spa', 'Novio o yerno; un hombre en relación con su novia en una boda, o el esposo de una hija en el parentesco familiar.', 'Novio o yerno; un hombre en relación con su novia en una boda, o el esposo de una hija en el parentesco familiar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2864', 'spa', 'Cavar, perforar — atravesar muros o tierra; también remar un bote, hundiendo los remos en el agua', 'El verbo חָתַר significa primariamente cavar o perforar una barrera sólida. Ezequiel recibe la orden de cavar a través del muro de Jerusalén como acto profético simbólico (Ez 8:8; 12:5, 7, 12), y Job describe a los ladrones que «cavan casas» al amparo de la oscuridad (Job 24:16). La palabra alcanza incluso lo mítico: Amós 9:2 imagina fugitivos intentando «cavar hasta el Seol» para esconderse de Dios. Una única y vívida aparición en Jonás 1:13 traslada por completo la imagen: los desesperados marineros «remaron con fuerza» (literalmente «cavaron en» el mar) tratando de llegar a tierra, otorgando al verbo un sentido náutico que explota el mismo movimiento físico de cavar aplicado al agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2865', 'spa', 'Ser quebrantado o desalentado; quebrar en pedazos; en causativo, aterrorizar o causar pavor ante un poder abrumador. Enraizado en la imagen concreta d', 'Ser quebrantado o desalentado; quebrar en pedazos; en causativo, aterrorizar o causar pavor ante un poder abrumador. Enraizado en la imagen concreta de algo que se quiebra o se hace pedazos, este verbo se extiende poderosamente al ámbito emocional del terror paralizante y el desaliento. En las grandes fórmulas de ánimo de Deuteronomio y Josué, se dice repetidamente a Israel que no «desmaye» (Dt 1:21; Jos 1:9), donde el español traduce consistentemente «desmayar», captando la idea del coraje que se derrumba ante el miedo. La forma causativa Hifil aparece en pasajes impactantes como Job 7:14 («Me espantas con sueños») y Jeremías 1:17, donde Dios advierte al profeta que no se quebrante ante sus oponentes, no sea que Dios mismo lo quebrante. El sentido físico de ser roto o aplastado (Is 8:9; 30:31) constituye la base experiencial de la que brota el significado emocional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2873', 'spa', 'Degollar, matar — sacrificar un animal para alimento o sacrificio; por extensión, matar violentamente a personas', 'El verbo טָבַח (tavach) significa degollar o matar, y describe principalmente el sacrificio de animales para consumo. José ordena a su mayordomo que degüelle un animal y prepare un banquete (Gn 43:16), la Sabiduría personificada ha degollado sus reses para el festín del entendimiento (Pr 9:2), y el ladrón degüella el buey robado (Éx 22:1). Deuteronomio 28:31 contempla la maldición del pacto de ver al propio buey degollado ante los ojos del dueño. El verbo se extiende a la matanza violenta de personas en contextos de guerra y juicio: Lamentaciones 2:21 lamenta a jóvenes y ancianos degollados en las calles de Jerusalén, y Ezequiel 21:15 habla de una espada afilada para la matanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2874', 'spa', 'Matanza, degüello — acción de matar y preparar animales para alimento o banquete; también masacre en batalla', 'El sustantivo טֶבַח (tebach) abarca desde la preparación doméstica de alimentos hasta la matanza a gran escala. José ordena a su mayordomo que prepare un degüello (טְבֹחַ טֶבַח) cuando dispone el banquete para sus hermanos (Gn 43:16). Proverbios personifica a la Sabiduría como quien ha realizado su matanza para un festín (Pr 9:2). Pero la palabra también posee un registro más sombrío: Isaías describe el día escatológico de Yahvé como una matanza en Bosra (Is 34:2, 6), y Jeremías y Ezequiel la emplean para referirse al degüello de los enemigos (Jer 48:15; Ez 21:15, 33). El término abarca tanto el uso doméstico como el militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2876', 'spa', 'Verdugo real o guardia de corps (''degollador''); raramente, un cocinero que mata y prepara alimentos.', 'Verdugo real o guardia de corps (''degollador''); raramente, un cocinero que mata y prepara alimentos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2878', 'spa', 'Carne sacrificada, animal destinado a la matanza', 'Carne de animales sacrificados, o el acto de degollar para alimento o sacrificio. El término aparece tanto en contextos cotidianos (preparar carne para una comida) como metafóricos (Israel como ovejas para el matadero). Deriva de la raíz que significa degollar o carnear. En 1 Samuel, la esposa de Nabal menciona la carne que su esposo preparó para los esquiladores. Los Salmos y Jeremías lo usan metafóricamente para los justos o los impíos llevados como ovejas al matadero, vulnerables y destinados a la muerte. La palabra enfatiza la preparación y designación de animales para ser sacrificados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2881', 'spa', 'Mojar, sumergir: meter un objeto en un líquido (sangre, agua, salsa); hundir o sumergir completamente; pasivo: ser mojado.', 'Mojar, sumergir: meter un objeto en un líquido (sangre, agua, salsa); hundir o sumergir completamente; pasivo: ser mojado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2883', 'spa', 'Hundirse, sumergirse — de objetos que se clavan en materia sólida o personas tragadas por agua o cieno', 'Un verbo de movimiento descendente que transmite un vívido peso físico: algo o alguien se hunde en una sustancia y permanece allí. La frente de Goliat absorbe la piedra (1 S 17:49), Jeremías desciende en el lodo de una cisterna (Jer 38:6) y las puertas de Jerusalén se hunden en la tierra como si el suelo mismo las devorara (Lm 2:9). Los Salmos extienden la imagen a la angustia espiritual: el clamor «me he hundido en cieno profundo» (Sal 69:2) resuena con fuerza. En Éxodo 15:4 el Pual intensifica el cuadro: los carros del faraón son completamente ahogados, sumergidos sin posibilidad de rescate.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2885', 'spa', 'Anillo; un anillo de metal usado como argolla funcional para transportar objetos sagrados o como anillo de sello, símbolo de autoridad y ornamento. Su', 'Anillo; un anillo de metal usado como argolla funcional para transportar objetos sagrados o como anillo de sello, símbolo de autoridad y ornamento. Sustantivo que designa un anillo, con apariciones en dos contextos materiales distintos en la Biblia hebrea. La gran mayoría de ocurrencias (40 de 50) describe los anillos de oro o bronce fijados al arca, al altar del incienso, a la mesa de los panes de la proposición y al efod sacerdotal — argollas funcionales a través de las cuales se insertaban las varas de transporte. El español distingue estas como «argollas» frente a «anillo» (de dedo), una reveladora división léxica. Las diez ocurrencias restantes describen anillos de sello llevados en la mano como símbolos de autoridad real: el anillo de Faraón dado a José (Gn 41:42), el anillo de sello de Asuero transferido a Amán y luego a Mardoqueo (Est 3:10; 8:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2889', 'spa', 'Limpio o puro — ritualmente limpio según la ley levítica, puro en sustancia material (p. ej., oro puro), moral o espiritualmente puro, o pureza como s', 'Limpio o puro — ritualmente limpio según la ley levítica, puro en sustancia material (p. ej., oro puro), moral o espiritualmente puro, o pureza como sustantivo abstracto. El adjetivo טָהוֹר es uno de los pilares del sistema de pureza levítica, y aparece en contextos que van desde la clasificación de animales hasta la orfebrería y la vida interior del alma. Su uso más frecuente — unas sesenta ocurrencias — concierne a la pureza ritual: animales limpios aptos para el sacrificio (Gn 7:2; Lv 20:25), personas limpias que pueden comer alimento sagrado, lugares limpios donde se depositan las cenizas. Un segundo grupo importante describe la pureza material, especialmente «oro puro» (zahav tahor) en las instrucciones del tabernáculo de Éxodo 25–39. El uso más raro pero teológicamente más rico aparece en el Salmo 19:9, donde el temor del SEÑOR es llamado tahor — moral y espiritualmente limpio, que permanece para siempre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2891', 'spa', 'Estar limpio o puro; en Piel, limpiar o declarar limpio; en Hitpael, purificarse a sí mismo — de pureza ritual, moral y física. Un verbo fundamental d', 'Estar limpio o puro; en Piel, limpiar o declarar limpio; en Hitpael, purificarse a sí mismo — de pureza ritual, moral y física. Un verbo fundamental de pureza que abarca la ley ritual, la teología moral e incluso la sanación física. En Qal describe el estado de estar limpio — ya sea un leproso sanado al lavarse en el Jordán (2 R 5:10-14) o un utensilio apto tras la contaminación (Lv 11:32). El Piel tiene una doble fuerza: factitiva (purificar activamente, como cuando Dios promete «Yo os limpiaré», Ez 36:25) y declarativa (la declaración formal del sacerdote de pureza en Lv 13–14). El Hitpael capta el acto reflexivo de autopurificación, como cuando la familia de Jacob se purificó antes de ir a Betel (Gn 35:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2893', 'spa', 'Purificación, limpieza ritual — el proceso prescrito para restaurar la pureza ceremonial', 'Sustantivo femenino central en el sistema de pureza de Israel, que designa el proceso formal mediante el cual una persona u objeto es restaurado a un estado de limpieza ritual ante Dios. Tras el parto, la mujer observa ''días de su purificación'' — treinta y tres para un varón, sesenta y seis para una hija (Lv 12:4–6). Un leproso sanado pasa por un elaborado rito de purificación (Lv 14:2, 23, 32), y un nazareo contaminado por muerte súbita debe reiniciar su purificación (Nm 6:9). Ezequiel requiere siete días de purificación para los sacerdotes tras contacto con los muertos (Ez 44:26), y Nehemías celebra que los levitas guardaron ''el deber de la purificación'' (Neh 12:45).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2895', 'spa', 'Ser bueno, agradable o placentero; en tallos causativos, hacer bien, actuar correctamente o tratar generosamente a alguien', 'Ser bueno, agradable o placentero; en tallos causativos, hacer bien, actuar correctamente o tratar generosamente a alguien');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2896a', 'spa', 'Bueno, agradable, grato; de calidad moral, aptitud práctica, belleza o alegría; también sustantivado como «bondad» o «bienestar».', 'Pocas palabras hebreas son tan omnipresentes o tan engañosamente simples como טוֹב. Con más de 400 apariciones, abarca desde la declaración divina de que la creación es «buena» (Gn 1:4), pasando por una mujer «hermosa de aspecto» (Gn 26:7), hasta un corazón «alegre» por el vino (Jue 16:25). La forma comparativa («mejor que») es especialmente prominente en la literatura sapiencial, donde Eclesiastés y Proverbios sopesan repetidamente una condición contra otra. Lo fascinante de טוֹב en perspectiva interlingüística es cómo los traductores deben elegir constantemente entre vocabulario moral, estético y emocional: el árabe distingue entre khayr (bien moral), ḥasan (bello) y ṭayyib (agradable); el español alterna entre bueno, mejor y hermosa. La unidad de la palabra en hebreo —una sola raíz que abarca todos estos dominios— es en sí misma una declaración teológica sobre la coherencia del orden creado por Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2896b', 'spa', 'Bien, bondad; lo que es bueno, beneficioso o recto; también prosperidad, bienestar y cualidad intrínseca de bondad. Usado como sustantivo, טוֹב abarca', 'Bien, bondad; lo que es bueno, beneficioso o recto; también prosperidad, bienestar y cualidad intrínseca de bondad. Usado como sustantivo, טוֹב abarca tanto el concepto moral abstracto de «el bien» como sus manifestaciones concretas en la vida humana. Desde el Árbol del Conocimiento del Bien y del Mal en Génesis hasta la oración del salmista «¿Quién nos mostrará el bien?» (Sal 4:6), ancla una categoría bíblica fundamental. La palabra aparece frecuentemente en oposición a רַע («mal»), y este par se refleja en todas las lenguas: español «bien» frente a «mal», francés «bon» frente a «mal». Algunos pasajes estrechan el enfoque a la prosperidad material — la buena vida, circunstancias favorables — mientras que un grupo aún menor resalta la cualidad intrínseca o excelencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2896c', 'spa', 'Bondad, bienestar, beneficio; cosas buenas o buenas obras concretas; generosidad divina — forma nominal femenina del adjetivo «bueno». Este sustantivo', 'Bondad, bienestar, beneficio; cosas buenas o buenas obras concretas; generosidad divina — forma nominal femenina del adjetivo «bueno». Este sustantivo femenino da peso abstracto al concepto hebreo de «bueno», pasando más allá del simple adjetivo para nombrar la cosa en sí: bondad, bienestar, beneficio. Cuando José dice a sus hermanos que Dios convirtió su mala intención «para bien» (Gn 50:20), la palabra lleva toda la carga teológica de la providencia divina que redirige el daño en bendición. Aparece en bendiciones del pacto (Dt 28:11; 30:9), juicios proféticos que contrastan bienestar con calamidad (Jer 21:10; Am 9:4), y la confesión íntima del salmista de que todo bienestar personal depende del Señor (Sal 16:2). Las formas plurales pueden nombrar bendiciones concretas o buenas obras, mientras que los sufijos posesivos dirigidos a Dios lo elevan a «Tu bondad» (Sal 65:11; 68:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2897', 'spa', 'Tob — región al este del Jordán, al norte o noreste de Galaad, probablemente territorio arameo.', 'Nombre propio que designa una región situada al este del Jordán, probablemente en las cercanías del sur de Basán. Jefté huyó allí tras ser expulsado por sus hermanos (Jue 11:3, 5), y sus hombres aparecen como mercenarios aliados de los amonitas contra David (2 Sam 10:6, 8). El nombre significa «bueno» en hebreo, y todas las traducciones principales lo transliteran simplemente como «Tob». Se identifica comúnmente con la zona cercana a la actual Taiyibeh, al sureste del mar de Galilea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2898', 'spa', 'Cosas buenas, bienes, bondad; abarca desde la abundancia material y las propiedades hasta la bondad moral abstracta y la belleza.', 'Cosas buenas, bienes, bondad; abarca desde la abundancia material y las propiedades hasta la bondad moral abstracta y la belleza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2900', 'spa', 'Tobías/Tobiyyahu: ''Yah es mi bien''; un levita maestro, el adversario amonita de Nehemías y otras figuras bíblicas.', 'Tobías/Tobiyyahu: ''Yah es mi bien''; un levita maestro, el adversario amonita de Nehemías y otras figuras bíblicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2902a', 'spa', 'Revocar, enlucir, encalar — untar una superficie con cal, arcilla o enjalbegado; uso literal y metafórico', 'El verbo טוּחַ (tuach) significa revocar, enlucir o recubrir una superficie con cal, arcilla o enjalbegado. Su uso literal más notable aparece en las instrucciones levíticas para tratar una casa afectada por moho o «lepra», donde las paredes son raspadas, revocadas de nuevo e inspeccionadas (Lv 14:42-48). David apartó oro para el revestimiento del templo (1 Cr 29:4), donde el verbo describe el proceso de dorar. Ezequiel transforma la palabra en una devastadora metáfora: los falsos profetas «revocan con enjalbegado» (Ez 13:10-15; 22:28), dando a los frágiles muros de falsedad un engañoso barniz de respetabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2903', 'spa', 'Frontales, filacterias; bandas llevadas en la frente como señal de devoción a la Torá', 'Bandas o marcas llevadas en la frente, entre los ojos, mencionadas en los mandamientos de Deuteronomio para recordar la ley de Dios. El término aparece en pasajes que ordenan a Israel atar las palabras de Dios como señal en las manos y como frontales entre los ojos. Originalmente fue probablemente lenguaje figurado para la atención constante a la Torá, pero la tradición judía posterior interpretó estos mandatos literalmente, desarrollando la práctica de usar filacterias (tefilín) con textos bíblicos. La palabra designa bandas u ornamentos frontales que sirven como recordatorios visibles del compromiso del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2904', 'spa', 'Arrojar, lanzar con fuerza; (pasivo) ser arrojado o derribado; ser derrocado', 'Verbo hebreo de movimiento violento cuya imagen raíz es el lanzamiento enérgico de un objeto o persona. Saúl arroja su lanza contra David (1 S 18:11; 20:33), Jeremías advierte del exilio como Dios arrojando a su pueblo a tierra extranjera (Jer 16:13; 22:26), e Isaías describe a Dios lanzando violentamente a un hombre como una pelota (Is 22:17). La intensificación del Pilpel en ese pasaje de Isaías capta la fuerza bruta latente en la raíz. En sus formas pasivas del Hofal, la palabra describe la experiencia de ser arrojado o derribado, ya sea la suerte echada en el regazo (Pr 16:33) o el guerrero que cae pero no es abandonado (Sal 37:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2905', 'spa', 'Hilera, hilada o fila — una línea horizontal ordenada de piedras, joyas, columnas o vigas en contextos arquitectónicos o sacerdotales', 'Hilera, hilada o fila — una línea horizontal ordenada de piedras, joyas, columnas o vigas en contextos arquitectónicos o sacerdotales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2912', 'spa', 'Moler grano o material con piedra de molino; por extensión, triturar o reducir a polvo', 'Describe la tarea cotidiana de moler con piedras de molino, típicamente trabajo de mujeres en el hogar antiguo. Aparece en contextos que van desde lo mundano — moler el maná con molinos de mano en el desierto (Núm 11:8) — hasta lo humillante: Sansón moliendo en la prisión filistea (Jue 16:21), y la molienda metafórica de los pobres por gobernantes opresores (Is 3:15). Los cognados en otras lenguas semíticas (arameo, árabe, etiópico) comparten la misma acción de molienda. Job 31:10 lo emplea como figura de sujeción servil: «muela mi esposa para otro».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2914', 'spa', 'Tumores o hemorroides; la plaga que Dios envió sobre los filisteos tras capturar el arca', 'Este sustantivo plural aparece casi exclusivamente en la narrativa de la plaga filistea tras la captura del arca (1 Sam 5-6), además de la lista de maldiciones deuteronómicas (Dt 28:27). La tradición del Qeré sustituye consistentemente este término por la lectura del Ketiv ofalim («hinchazones»), lo que sugiere que los masoretas lo consideraban más preciso o apropiado. Los filisteos fabricaron réplicas de oro de estos tumores como ofrendas de culpa (1 Sam 6:4-5, 11, 17), testimonio vívido de la gravedad de la aflicción. Los términos «hemorroides» y «tumores» reflejan la ambigüedad médica persistente sobre si se trataba de hinchazones hemorroidales, tumores bubónicos u otra patología.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2916', 'spa', 'Lodo, cieno, barro — tierra húmeda pisoteada o moldeada por el alfarero', 'Sustantivo que designa la tierra húmeda y pegajosa, presente en dos contextos distintos pero relacionados. Con mayor frecuencia describe el cieno de las calles, evocando desprecio y humillación — enemigos pisoteados como lodo en los caminos (2 S 22:43; Mi 7:10; Zac 10:5). También retrata el fango de la cisterna donde fue echado Jeremías (Jer 38:6) y el pantano de angustia en los Salmos (Sal 40:2; 69:14). En pasajes poéticos designa el barro del alfarero o para la fabricación de ladrillos (Is 41:25; Nah 3:14), en paralelo con el más común חֹמֶר. El núcleo semántico es la tierra húmeda y maleable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2918', 'spa', 'Sustantivo femenino que significa ''campamento, asentamiento, aldea nómada''; también ''almena, hilera de piedras''', 'Derivado de la idea raíz de cercar o rodear (compárese el siríaco ''redil de ovejas''), este sustantivo describe tanto asentamientos nómadas como elementos arquitectónicos. Los doce príncipes de Ismael habitan en sus טִירוֹת junto con sus חֲצֵרִים (''aldeas'') en Génesis 25:16, evocando campamentos circulares de tiendas. La misma palabra aparece en contextos militares cuando Israel quema los campamentos madianitas (Números 31:10). En un giro arquitectónico sorprendente, Cantares 8:9 la emplea para una ''almena de plata'', y Ezequiel 46:23 la aplica a hileras de mampostería alrededor de los atrios del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2919', 'spa', 'Rocio, humedad nocturna — condensacion atmosferica que simboliza la bendicion divina, el refrigerio y la abundancia.', 'Rocio, humedad nocturna — condensacion atmosferica que simboliza la bendicion divina, el refrigerio y la abundancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2920', 'spa', 'Rocío (arameo); el rocío del cielo como símbolo de exposición a la intemperie y humillación divina', 'Sustantivo arameo para rocío, que aparece exclusivamente en el relato de Daniel sobre la locura de Nabucodonosor. Cinco veces el texto declara que el cuerpo del rey sería ''mojado con el rocío del cielo'' — un motivo reiterado que subraya su reducción del esplendor real a una exposición animal a la intemperie. La expresión ''rocío del cielo'' (טַל שְׁמַיָּא) se convierte casi en un estribillo. El español ''rocío'' capta bien ese fenómeno natural suave pero implacable que marca el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2921', 'spa', 'Manchado, moteado, abigarrado — de ganado multicolor; también remendado, de prendas desgastadas', 'El verbo טָלָא significa estar manchado o remendado, y sus dos sentidos se corresponden con dos célebres narrativas bíblicas. En su participio pasivo Qal, describe el ganado manchado y moteado del astuto pacto de Jacob con Labán (Gn 30:32-39), donde טָלוּא aparece junto a נָקֹד («moteado») y עָקֹד («listado») para designar los animales abigarrados que serían el salario de Jacob. En Ez 16:16 describe los santuarios idolátricos de colores llamativos. Su participio Pual aparece una sola vez en el engaño gabaonita (Jos 9:5), donde las «sandalias remendadas» sirven de utilería en un elaborado ardid: la misma raíz que nombra las marcas coloridas de los animales ahora describe remiendos en zapatos gastados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2929', 'spa', 'Talmón, familia de porteros levíticos en la Jerusalén postexílica', 'Nombre propio que identifica a una familia de porteros levíticos que servían en las puertas del templo. Talmón aparece en la lista de levitas que regresaron del exilio (Esd 2:42; Neh 7:45) junto a otras familias de porteros como Salum y Acub. Sus descendientes continuaron sirviendo como guardianes en la Jerusalén reconstruida (1 Cr 9:17; Neh 11:19; 12:25). El nombre perdura a lo largo de siglos de servicio en el templo, desde el regreso inicial hasta las reformas de Nehemías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2930a', 'spa', 'Ser o volverse ritualmente impuro, contaminar, declarar impuro; abarca impureza estativa, contaminación causativa y pronunciamiento sacerdotal', 'טָמֵא es el gran verbo de la legislación bíblica sobre la pureza, y rige la frontera entre lo puro y lo impuro que estructura la religión levítica de principio a fin. Sus conjugaciones despliegan una gramática completa de la contaminación: el Qal registra el estado de ser impuro, el Piel contamina activamente, el Nifal marca el resultado de haber sido contaminado, el Hitpael capta la autocontaminación deliberada y, de manera notable, un Piel declarativo otorga al sacerdote la autoridad de pronunciar la impureza. Desde la contaminación por contacto con cadáveres hasta la transgresión sexual y la polución idolátrica, טָמֵא cartografía todo el paisaje de lo que separa a Israel de la santidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2931', 'spa', 'Impuro; ritualmente inmundo o moralmente contaminado, lo opuesto de tahor (limpio/puro). טָמֵא es el adjetivo que describe lo que es ritual o moralmen', 'Impuro; ritualmente inmundo o moralmente contaminado, lo opuesto de tahor (limpio/puro). טָמֵא es el adjetivo que describe lo que es ritual o moralmente inmundo en el sistema de pureza de Israel. Clasifica a los animales prohibidos como alimento (Lv 11:8), a las personas contaminadas por enfermedad, flujo corporal o contacto con los muertos (Lv 13–15; Nm 19), y condiciones de contaminación moral como los «labios impuros» de Isaías (Is 6:5). El término se encuentra en constante oposición a tahor (limpio), y este binomio estructura gran parte de la legislación levítica. Las traducciones distinguen este concepto con consistencia: español «impuro», francés «impur», alemán «unrein» — cada uno preservando la connotación ritual-legal de un estado que requiere purificación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2932', 'spa', 'Inmundicia, impureza; contaminacion ritual o corrupcion moral que inhabilita para el contacto con lo sagrado.', 'Inmundicia, impureza; contaminacion ritual o corrupcion moral que inhabilita para el contacto con lo sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2934', 'spa', 'Esconder o ocultar en la tierra o en un lugar secreto; enterrar, empotrar; en voz pasiva, estar escondido; como sustantivo, tesoros ocultos.', 'Esconder o ocultar en la tierra o en un lugar secreto; enterrar, empotrar; en voz pasiva, estar escondido; como sustantivo, tesoros ocultos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2935', 'spa', 'Canasta utilizada para transportar productos agrícolas, especialmente primicias y cosechas.', 'Designa una canasta destinada específicamente al transporte de productos agrícolas. Aparece en la ceremonia de las primicias, donde el adorador coloca los frutos en la canasta y los presenta ante el Señor (Deut 26:2, 4). En las bendiciones y maldiciones de Deuteronomio 28:5, 17, se empareja con la artesa de amasar como símbolo de la provisión diaria, ya sea bendecida o maldecida. Se trata de un recipiente común y utilitario, no de un objeto ritual especializado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2938', 'spa', 'Gustar, probar alimento o bebida literalmente; por extensión, percibir o discernir mediante la experiencia', 'Un verbo sensorial enraizado en el acto físico de gustar: llevar algo a la boca y percibir su sabor. La mayoría de sus apariciones describen el acto literal de comer en pequeña cantidad, como cuando el ejército de Saúl tenía prohibido probar alimento (1 S 14:24) o cuando David se negó a probar pan durante el duelo (2 S 3:35). El salmista invita a los fieles a «gustar y ver que Yahvé es bueno» (Sal 34:8), fusionando lo literal con lo experiencial. Un notable uso figurado aparece en Proverbios 31:18, donde la mujer virtuosa «gusta» — percibe por experiencia — que su ganancia es buena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2939', 'spa', 'Gustar, probar; en la forma Pael, dar de comer o alimentar (arameo); también estar bajo el efecto del vino.', 'Verbo arameo que aparece en Daniel con el sentido básico de gustar o probar, y en la forma causativa Pael, alimentar o hacer comer a alguien. Nabucodonosor es alimentado con hierba como un buey durante su locura (Dan 4:25, 32; 5:21), mientras que en Daniel 5:2 Belsasar actúa «bajo el efecto del» (literalmente «en el gusto del») vino. La gama que abarca desde la alimentación literal hasta la experiencia metafórica de estar bajo la influencia del vino refleja la riqueza sensorial de este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2940', 'spa', 'Sabor, gusto; en sentido figurado, discernimiento, buen juicio; también conducta o comportamiento; en uso tardío, decreto real', 'Comienza en la lengua y termina en el trono. En su sentido más concreto, טַעַם es el sabor del maná — ''como hojuelas con miel'' (Éx 16:31). Del gusto físico se extiende naturalmente a la facultad de discernimiento: Abigail es elogiada por su טַעַם, su buen juicio (1 S 25:33), y los ancianos pierden el suyo cuando Dios se lo quita (Job 12:20). David célebremente ''mudó su conducta'' (שִׁנָּה טַעְמוֹ) ante Aquis, fingiendo locura (1 S 21:14). En Jonás 3:7, la palabra adquiere su coloración aramea como decreto real — un desarrollo tardío que vincula gusto, juicio y decisión autoritativa en un solo arco semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2941', 'spa', 'Gusto, juicio, discrecion; informe oficial o decreto (arameo)', 'Sustantivo arameo con un campo semantico notablemente amplio, que va desde el gusto fisico hasta el juicio abstracto, el informe oficial y el decreto real. En Daniel 5:2 designa el gusto literal — mientras se saborea el vino. En Daniel 2:14 denota discrecion y tacto. Como termino administrativo, se refiere a un informe oficial enviado al rey (Esdras 5:5) y a decretos emitidos por autoridad real o divina (Dan 3:10; Esd 6:14; 7:23). Solo el contexto determina cual sentido esta activo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2942', 'spa', 'Decreto, mandato; atención, consideración; discreción, juicio (arameo, en Esdras-Daniel)', 'Decreto, mandato; atención, consideración; discreción, juicio (arameo, en Esdras-Daniel)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2945', 'spa', 'Pequenos, ninos pequenos — sustantivo colectivo para los dependientes jovenes de una familia o comunidad.', 'Pequenos, ninos pequenos — sustantivo colectivo para los dependientes jovenes de una familia o comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2947', 'spa', 'Palmo menor (unidad de medida lineal, aprox. 7-8 cm); también término arquitectónico, posiblemente cornisa o repisa.', 'Se refiere principalmente al palmo menor, una antigua unidad de medida equivalente al ancho de cuatro dedos (aproximadamente 7-8 cm). Describe el grosor del mar de bronce de Salomón (1 Re 7:26; 2 Cr 4:5) y, en una conmovedora metáfora, la brevedad de la vida humana: «como palmos has hecho mis días» (Sal 39:5). En 1 Reyes 7:9 aparece como término arquitectónico, posiblemente designando una cornisa o repisa saliente. El español «palmo» y «cornisa» reflejan bien esta doble función semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2948', 'spa', 'Palmo menor; unidad de medida lineal equivalente a unos cuatro dedos de ancho', 'Unidad de medida lineal basada en el ancho de la palma, equivalente a unos 7,4 centimetros o tres pulgadas. Aparece en descripciones de mobiliario y arquitectura sagrados: el borde alrededor de la mesa del tabernaculo (Ex 25:25; 37:12), la medida adicional que distingue el codo largo del codo comun en la vision del templo de Ezequiel (Ez 40:5; 43:13), y el ancho de los rebordes en las mesas de sacrificio (Ez 40:43). Todas sus apariciones involucran mediciones sagradas precisas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2950', 'spa', 'Embadurnar, recubrir, enlucir (frecuentemente con engaño o falsedad)', 'Embadurnar o enlucir algo, generalmente con connotaciones negativas de encubrimiento o falsificación. El verbo aparece principalmente en Job y Salmos, describiendo el acto de recubrir la verdad con falsedad o acumular transgresión sobre transgresión. La imagen evoca el enlucido de una pared para ocultar sus defectos. Job acusa a sus amigos de ser «embadurnadores de mentira», encalando falsedades para hacerlas parecer verdad. El salmista describe a los arrogantes embadurnándolo con mentiras. El verbo capta el engaño mediante el encubrimiento y la falsificación mediante el revestimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2957', 'spa', 'Echar fuera, expulsar; usado para la expulsión de Nabucodonosor de la sociedad humana durante su locura.', 'Verbo arameo que significa echar fuera o expulsar, empleado exclusivamente en Daniel para describir el destierro de Nabucodonosor de la compañía humana durante su período de demencia. La forma pasiva («fue echado») aparece junto a la activa («te echarán»), pintando un vívido cuadro de humillación real. Las cuatro ocurrencias en Daniel (4:25, 32, 33; 5:21) narran cómo el rey fue arrojado de entre los hombres para vivir con los animales del campo, cumpliendo así el juicio divino anunciado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2962', 'spa', 'Antes, aún no; adverbio temporal que indica precedencia en el tiempo o el estado no realizado de un evento esperado. טֶרֶם es un adverbio hebreo singu', 'Antes, aún no; adverbio temporal que indica precedencia en el tiempo o el estado no realizado de un evento esperado. טֶרֶם es un adverbio hebreo singular, sin cognado conocido en otras lenguas semíticas, lo que lo convierte en una forma exclusivamente hebrea de expresar precedencia temporal. Típicamente rige un verbo en imperfecto para decir «antes de que X sucediera» — como en Génesis 2:5, donde las plantas «aún no» estaban en la tierra. La palabra también puede tener fuerza interrogativa, como cuando se le pregunta a Faraón «¿acaso todavía no sabes que Egipto está destruido?» (Éx 10:7). Una única aparición en el Salmo 5:5 podría extender el sentido espacialmente a «delante de», aunque la mayoría de los estudiosos lo leen incluso allí como temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2963', 'spa', 'Desgarrar, despedazar, tomar como presa; ser despedazado; proveer alimento, alimentar', 'Desgarrar, despedazar, tomar como presa; ser despedazado; proveer alimento, alimentar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2964', 'spa', 'Presa arrebatada por un depredador; alimento o provisión; hoja fresca o follaje', 'Presa arrebatada por un depredador; alimento o provisión; hoja fresca o follaje');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2966', 'spa', 'Animal despedazado por fieras; carne desgarrada prohibida como alimento bajo la ley mosaica', 'Sustantivo femenino que designa un animal matado por depredadores, lo cual hace que su carne sea ritualmente inapta para el consumo. La prohibición legal aparece repetidamente: Éxodo 22:31 prohíbe comer carne desgarrada en el campo, Levítico 7:24 y 17:15 la emparejan con nebelá (un animal que muere de forma natural), y Ezequiel 44:31 extiende la prohibición a los sacerdotes. La queja de Jacob a Labán — «lo despedazado yo cargaba con la pérdida» (Gn 31:39) — revela la realidad económica tras la ley: un pastor era normalmente responsable por las pérdidas de depredación. Nahúm 2:13 lo usa metafóricamente para Nínive como guarida de león llena de presa desgarrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2970', 'spa', 'Jaazanías — nombre propio hebreo que significa ''Yahvé escucha'', llevado por varios hombres del período monárquico tardío.', 'Nombre teofórico que significa ''Yahvé escucha'', llevado por al menos cuatro individuos distintos durante la monarquía tardía de Judá y el exilio. Uno fue un líder militar que se presentó ante Gedalías en Mizpa tras la caída de Jerusalén (2 Re 25:23). Otro fue un anciano sorprendido en idolatría secreta en la visión del templo de Ezequiel (Ez 8:11). Un líder recabita lleva este nombre en Jeremías 35:3, y un líder cívico corrupto aparece en Ezequiel 11:1. El nombre se transliteraba de forma consistente en las diversas lenguas antiguas y modernas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2971', 'spa', 'Jair, nombre propio que significa ''él ilumina''; llevado por un conquistador manasita, un juez galaadita y el padre de Mardoqueo.', 'El nombre Jair significa ''él ilumina'' o ''que Dios dé luz'', y pertenece al menos a tres figuras distintas en las Escrituras. El más destacado es Jair hijo de Manasés, quien conquistó las aldeas de tiendas en Galaad y las llamó Havot-Jair (''aldeas de Jair'', Nm 32:41; Dt 3:14; 1 R 4:13). Un segundo Jair sirvió como juez menor en Galaad, cuyos treinta hijos cabalgaban treinta asnos y controlaban treinta ciudades (Jue 10:3-5), una imagen memorable de prosperidad descentralizada. Un tercer Jair aparece como padre de Mardoqueo en Ester 2:5.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2973', 'spa', 'Obrar neciamente, volverse necio; mostrar insensatez moral o intelectual a causa del pecado o la falta de juicio.', 'Verbo en Nifal que significa actuar neciamente o volverse necio, con peso tanto moral como intelectual. En Números 12:11, Aarón confiesa que él y Miriam ''obraron neciamente'' al desafiar a Moisés, equiparando la necedad con el pecado. Jeremías 5:4 atribuye tal insensatez a la ignorancia de los caminos de Dios, mientras que Isaías 19:13 declara que los príncipes de Egipto ''se han enloquecido'', perdiendo todo juicio sensato. Jeremías 50:36 profetiza que los adivinos de Babilonia serán expuestos como necios. El verbo abarca un colapso tanto intelectual como moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2974', 'spa', 'Estar dispuesto, consentir, tener a bien; determinar, resolver, emprender; atreverse, osar (con humildad ante un superior).', 'Estar dispuesto, consentir, tener a bien; determinar, resolver, emprender; atreverse, osar (con humildad ante un superior).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2975', 'spa', 'El río Nilo (préstamo del egipcio); por extensión, cualquier río grande, corriente o canal de riego. יְאוֹר es una de las palabras prestadas más llama', 'El río Nilo (préstamo del egipcio); por extensión, cualquier río grande, corriente o canal de riego. יְאוֹר es una de las palabras prestadas más llamativas de la Biblia, tomada directamente del egipcio iotr/io''r («curso de agua»), conservada también en el copto eiero. En su uso dominante, es simplemente el Nilo: los sueños de Faraón se desarrollan «junto al יְאוֹר» (Gn 41:1-3), y las plagas lo convierten en sangre (Éx 7:20). Sin embargo, la palabra también funciona como sustantivo común para cualquier curso de agua importante — el Faraón de Ezequiel se jacta «mi יְאוֹר» (29:3), y 2 Reyes 19:24 habla de «los ríos (יְאוֹרֵי) de Egipto» en sentido genérico. En su uso más técnico, יְאוֹר designa los canales y acequias de riego del delta del Nilo (Éx 7:19; Is 19:6), reflejando la hidrología ingenieril de Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2976', 'spa', 'Desesperar, perder la esperanza (Nifal); causar desesperación, hacer que alguien se desaliente (Piel causativo).', 'Un verbo que expresa desesperanza y desesperación, que aparece con mayor frecuencia en la conjugación Nifal como participio con el sentido de ''desesperado'' o ''sin esperanza''. Los contemporáneos de Jeremías declaran נוֹאָשׁ — ''¡Es inútil!'' (Jer 2:25; 18:12), abrazando obstinadamente su ruina. David calcula que Saúl ''se desesperará de mí'' y dejará de perseguirlo (1 Sam 27:1). A Job se le llama ''desesperado'', cuyas palabras son como viento (Job 6:26). En su única aparición en Piel, Qohélet ''hace desesperar a su corazón'' por la futilidad del trabajo (Ecl 2:20), convirtiendo el verbo en causativo y reflexivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2977', 'spa', 'Josías — el rey reformador de Judá que redescubrió el Libro de la Ley y erradicó la idolatría. Yoshiyahu (''el SEÑOR sostiene'') fue el rey de Judá cuyo', 'Josías — el rey reformador de Judá que redescubrió el Libro de la Ley y erradicó la idolatría. Yoshiyahu (''el SEÑOR sostiene'') fue el rey de Judá cuyo reinado (640–609 a.C.) representa el último gran avivamiento espiritual antes del exilio babilónico. Sus 53 apariciones abarcan Reyes, Crónicas, Jeremías y Sofonías, trazando un arco narrativo extraordinario: coronado a los ocho años tras el asesinato de su padre Amón (2 Re 21:24–22:1), emprendió amplias reformas religiosas tras el hallazgo del Libro de la Ley en el Templo (2 Re 22:8–23:25), purificando los lugares altos, destruyendo el altar de Betel que se mantenía desde el cisma de Jeroboam y celebrando una Pascua sin igual desde los días de los jueces. Su muerte en Meguido al enfrentar al faraón Necao (2 Re 23:29) es lamentada por Jeremías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2981', 'spa', 'Producto, rendimiento — la cosecha que la tierra entrega de la tierra cultivada', 'Designa el producto agrícola o rendimiento que el suelo produce, casi siempre en la fórmula ''la tierra dará su fruto'' (Lv 26:4; Ez 34:27; Zac 8:12). Aparece en bendiciones del pacto que prometen abundancia y en maldiciones que amenazan esterilidad (Dt 11:17; Lv 26:20). Habacuc 3:17 acota el término específicamente a la cosecha de la vid, mientras que Job 20:28 lo extiende figuradamente al ''producto'' de la casa del impío que se lo lleva la corriente en el juicio divino. El núcleo semántico gira en torno a la cosecha de tierra húmeda y cultivada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2982', 'spa', 'Jebús, el antiguo nombre cananeo de Jerusalén antes de la conquista de David.', 'Nombre arcaico que identifica a Jerusalén por su designación jebusea preisraelita. El nombre aparece exclusivamente en narrativas que equiparan explícitamente ambas ciudades: ''Jebús, que es Jerusalén'' (Jue 19:10; 1 Cr 11:4), preservando la memoria del pasado cananeo de la ciudad. Su uso infrecuente (solo 4 apariciones) sugiere que ya era un término anticuario en el período bíblico, invocado para anclar la identidad de Jerusalén en la historia de la conquista davídica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2983', 'spa', 'Jebuseo — gentilicio del pueblo cananeo que habitaba Jerusalen (Jebus) antes de la conquista de David.', 'Jebuseo — gentilicio del pueblo cananeo que habitaba Jerusalen (Jebus) antes de la conquista de David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2984', 'spa', 'Ibhar: hijo de David nacido en Jerusalén; su nombre significa «Él (Dios) elige»', 'Hijo de David nacido después de que David se convirtió en rey en Jerusalén. El nombre significa «Él (Dios) elige», reflejando el patrón teofórico de nombres común en la cultura israelita. Ibhar aparece en las listas de los hijos de David tanto en Samuel como en Crónicas, entre los nacidos en Jerusalén, a diferencia de los nacidos en Hebrón. Más allá de estas referencias genealógicas, no se conoce nada más sobre él. Su inclusión en las listas confirma su legitimidad como heredero real, aunque no desempeñó ningún papel registrado en la política de sucesión ni en la historia de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2985', 'spa', 'Jabín (''él discierne''), nombre dinástico de reyes cananeos de Hazor derrotados por Israel.', 'Nombre propio que significa ''él entiende'' o ''él es inteligente'', portado por dos reyes cananeos de la poderosa ciudad-estado de Hazor. El primer Jabín organizó una coalición norteña contra Josué y fue derrotado junto a las aguas de Merom (Jos 11:1). El segundo, probablemente un título dinástico más que un nombre personal, oprimió a Israel durante veinte años hasta que Débora y Barac quebrantaron su poder mediante la derrota de su general Sísara (Jue 4:2-24). El Salmo 83:9 recuerda esta victoria como paradigma de liberación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2986', 'spa', 'Guiar, llevar o conducir en procesión (Hifil); ser guiado o llevado (Hofal).', 'Guiar, llevar o conducir en procesión (Hifil); ser guiado o llevado (Hofal).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2987', 'spa', 'traer, llevar, transportar (arameo)', 'Verbo arameo que significa traer o llevar algo de un lugar a otro. En el relato de Esdras sobre la restauración del templo, describe el transporte de los vasos sagrados que Nabucodonosor había tomado del templo de Jerusalén. La forma Hafel (equivalente arameo del Hifil hebreo) indica acción causativa: hacer que algo sea traído o llevado. El verbo aparece en correspondencia oficial sobre la devolución de los artículos del templo a Jerusalén, enfatizando el traslado físico de objetos desde Babilonia de vuelta a su lugar legítimo en el templo restaurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2991', 'spa', 'Ibleam: ciudad de Manasés en el norte de Israel', 'Ciudad asignada a Manasés en la región del valle de Jezreel, aunque ubicada dentro del territorio de Isacar o Aser. Ibleam aparece en los relatos de la conquista donde Israel no logró expulsar a los habitantes cananeos. También marca el lugar donde el rey Ocozías de Judá fue herido de muerte mientras huía de Jehú. La ciudad corresponde a Bileam en la lista paralela de ciudades levíticas de Crónicas. Su ubicación estratégica en el valle la hacía importante para controlar las rutas comerciales. Su etimología permanece incierta, aunque aparece en registros egipcios del segundo milenio a.C.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2992', 'spa', 'cumplir el deber de levirato, desposar a la viuda del hermano', 'Cumplir el deber de cuñado (yabam) desposando a la viuda sin hijos del hermano fallecido. Esta antigua costumbre del Cercano Oriente buscaba preservar el nombre y la herencia del difunto engendrando descendencia a través de la viuda. El verbo en Piel aparece en contextos donde se ordena o discute esta obligación. Génesis relata que Judá ordenó a Onán cumplir este deber con Tamar. Deuteronomio legisla la práctica, incluyendo disposiciones para el caso de rechazo. La costumbre involucraba dinámicas familiares, económicas y sociales complejas, equilibrando la protección de la viuda, la preservación del linaje y los derechos de propiedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2994', 'spa', 'Cunada; esposa del hermano (viuda) en el contexto del matrimonio levirato', 'Termino de parentesco que designa a la esposa del hermano de un hombre, usado exclusivamente en el contexto de la ley del matrimonio levirato. En Deuteronomio 25:7-9, se refiere a la viuda que el hermano sobreviviente esta obligado a desposar, y cuya ceremonia publica de quitar la sandalia avergüenza al que se niega. En Rut 1:15, Noemi emplea el termino al instar a Rut a seguir a Orfa — ''tu cunada'' — de regreso a Moab. La palabra encierra toda una obligacion legal y familiar en un solo vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2999', 'spa', 'Jaboc, río en Transjordania (actual Zarqa) que sirvió como frontera territorial y lugar de la lucha de Jacob', 'El Jaboc (יַבֹּק) es uno de los ríos más significativos al este del Jordán, tanto geográfica como teológicamente. Es el lugar donde Jacob luchó toda la noche con un ser divino antes de reencontrarse con Esaú (Gn 32:22), episodio que le otorgó el nuevo nombre Israel. Además de este dramático encuentro, el Jaboc aparece repetidamente como marcador fronterizo: el límite norte del reino amorreo de Sehón y el borde occidental del territorio amonita (Nm 21:24; Dt 2:37; 3:16; Jos 12:2; Jue 11:13, 22). Actualmente se identifica con el río Zarqa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3001', 'spa', 'Secarse o marchitarse; en sentido causativo, hacer secar; por extensión (Hifil), ser avergonzado. Yavesh abarca una realidad física vívida —el secarse', 'Secarse o marchitarse; en sentido causativo, hacer secar; por extensión (Hifil), ser avergonzado. Yavesh abarca una realidad física vívida —el secarse del agua, el marchitarse de la vegetación, la aridez de la tierra— y luego da un salto semántico sorprendente hacia el ámbito de la vergüenza. En su forma básica Qal describe las aguas del Jordán secándose (Jos 4:23), la hierba marchitándose bajo el viento abrasador (1 Re 17:7) y la visión de Ezequiel de los huesos secos (Ez 37:11). El Hifil causativo tiene a Dios como sujeto característico: ''Él secó el mar Rojo'' (Jos 2:10). Pero la misma forma Hifil también significa ''avergonzar'' (Jer 6:15; 2 Sam 19:5), quizá porque la vergüenza hace que una persona se marchite y se encoja socialmente, así como la sequía marchita una planta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3002', 'spa', 'Seco, reseco o marchito; describe lo que ha perdido su humedad, ya sea literal o como figura de desolación espiritual.', 'Forma adjetival de la raíz י-ב-שׁ que significa ''seco'' o ''marchito'', aplicada tanto a la sequedad física como a la aridez espiritual y metafórica. Las uvas secas (Nm 6:3) representan el extremo literal, mientras que la queja ''nuestra alma está reseca'' (Nm 11:6) convierte la sed física en anhelo existencial. La visión de Ezequiel sobre los huesos secos (Ez 37:2, 4) transforma el adjetivo en una de las imágenes más poderosas de la Escritura sobre la desesperanza que aguarda resurrección. La metáfora del ''árbol seco'' cumple doble función: símbolo de la casa davídica humillada (Ez 17:24) y del eunuco que se considera estéril (Is 56:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3003', 'spa', 'Jabes -- ciudad de Jabes de Galaad en Transjordania; también el padre del rey Salum de Israel', 'Jabes -- ciudad de Jabes de Galaad en Transjordania; también el padre del rey Salum de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3004', 'spa', 'Tierra seca, suelo firme — especialmente como camino a través de aguas divididas o como tierra distinta del mar', 'Sustantivo femenino que significa tierra seca, empleado en vívido contraste con el agua a lo largo del Antiguo Testamento. En la creación, Dios ordena que las aguas se reúnan para que aparezca la יַבָּשָׁה (Gn 1:9–10). La palabra alcanza su clímax dramático en el éxodo: Israel cruza el Mar Rojo en seco (Éx 14:16, 22, 29; 15:19) y posteriormente el Jordán (Jos 4:22). Jonás confiesa que el Señor hizo tanto el mar como la tierra seca (Jon 1:9), y el gran pez lo vomita sobre la יַבָּשָׁה (Jon 2:10). Isaías la usa figuradamente para un Israel reseco que Dios refrescará con su Espíritu (Is 44:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3008', 'spa', 'Igal/Yigal: nombre personal (tres individuos diferentes)', 'Nombre personal hebreo que significa «Él (Dios) redime», llevado por tres individuos distintos en la narrativa bíblica. Primero, uno de los doce espías enviados a explorar Canaán, representando a la tribu de Isacar. Segundo, uno de los valientes de David. Tercero, un descendiente de la línea real de Zorobabel en la genealogía postexílica. El nombre refleja el patrón teofórico de incorporar la acción divina en los nombres personales. Cada portador pertenece a un período y contexto social diferente, lo que demuestra la popularidad duradera del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3013', 'spa', 'Causar aflicción, atormentar (causativo); estar afligido, padecer tristeza (pasivo-reflexivo).', 'El verbo יָגָה abarca el dolor tanto en su imposición como en su experiencia. En sus formas causativas (Hifil y Piel), describe la acción de provocar aflicción: Dios ''no aflige de corazón'' a los hijos de los hombres (Lm 3:33), pero los enemigos de Jerusalén ''la han afligido'' (Lm 1:5, 12) y los amigos de Job lo ''atormentan'' con palabras (Job 19:2). El Nifal pasivo vuelve la mirada hacia dentro: las vírgenes de Sion ''están afligidas'' (Lm 1:4) y los desterrados dolientes de Sof 3:18 cargan el peso de las fiestas perdidas. El cognado árabe وَجِىَ (''tener dolor, estar llagado'') insinúa raíces físicas bajo la superficie emocional de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3015', 'spa', 'Tristeza, pesar, angustia; dolor emocional profundo y aflicción persistente, a menudo emparejada con duelo o congoja', 'Sustantivo que denota el peso profundo y persistente del pesar — ese tipo de dolor que se instala y no se levanta. Jacob teme que lo acompañe hasta la tumba si pierde a Benjamín (Gn 42:38; 44:31), y el salmista pregunta cuánto tiempo reinará la tristeza en su corazón (Sal 13:2). Los profetas emparejan יָגוֹן con el suspiro (אֲנָחָה) en Isaías 35:10 y 51:11, prometiendo que la tristeza y el suspiro huirán cuando los redimidos de Dios regresen a Sion. Jeremías 31:13 lo contrapone a שִׂמְחָה (''gozo''), vislumbrando que Dios convertirá el duelo en alegría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3018', 'spa', 'Trabajo, labor, esfuerzo; también el producto o fruto del propio trabajo, bienes adquiridos.', 'Trabajo, labor, esfuerzo; también el producto o fruto del propio trabajo, bienes adquiridos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3021', 'spa', 'Afanarse o fatigarse; en Hifil, cansar o agotar a alguien; abarca tanto el esfuerzo como la fatiga que produce', 'Afanarse o fatigarse; en Hifil, cansar o agotar a alguien; abarca tanto el esfuerzo como la fatiga que produce');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3023', 'spa', 'cansado, agotado, fatigoso', 'Física o mentalmente agotado, fatigado por el trabajo o la adversidad. El adjetivo describe tanto a personas desgastadas por el esfuerzo como a cosas que resultan fatigosas o agotadoras. Deuteronomio lo emplea para Israel cuando fue atacado por Amalec, cansado del viaje por el desierto. 2 Samuel lo aplica a David cuando huía de Absalón, exhausto y vulnerable. Eclesiastés lo usa filosóficamente: todas las palabras y las cosas son fatigosas, llenas de un trabajo que excede toda expresión. El término capta el estado de agotamiento tras un esfuerzo prolongado, sea fatiga física o cansancio existencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3025', 'spa', 'Temer, recelar; sentir pavor ante una amenaza percibida o la ira divina', 'Verbo que expresa un temor profundo o una ansiedad temerosa, frecuentemente dirigida hacia una fuente concreta de peligro. En Deuteronomio, Moises confiesa que temio la ardiente ira del SENOR tras el episodio del becerro de oro (Dt 9:19), y el termino reaparece para el pavor ante las enfermedades de Egipto (Dt 28:60). Job lo emplea de modo conmovedor: ''lo que tanto temia me ha sobrevenido'' (Job 3:25). La construccion con מִפְּנֵי (''ante la presencia de'') marca el objeto temido, ya sea la ira divina o una calamidad anticipada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3026a', 'spa', 'montón (de piedras) (término arameo usado en Génesis 31:47 paralelo al hebreo גַּל־עֵד)', 'Esta palabra aramea aparece en la célebre escena del pacto entre Jacob y Labán en Génesis 31:47. Labán, hablando en arameo, llama al montón de piedras testigo ''Yegar-Sahaduta'', mientras Jacob emplea el equivalente hebreo ''Galaad''. Ambos términos significan ''montón del testimonio'', señalando un límite pactado. El juego de palabras bilingüe en este pasaje refleja la división lingüística y étnica entre los pueblos arameoparlantes de Mesopotamia y los descendientes hebreoparlantes de Abraham, incluso mientras sellan la paz mediante prácticas compartidas de alianza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3026b', 'spa', 'testimonio, testigo (cognado arameo, aparece en Génesis 31:47 paralelo al hebreo עֵד)', 'Este término arameo para ''testimonio'' o ''testigo'' aparece en estado enfático como parte del nombre compuesto que Labán da al montón del pacto en Génesis 31:47. La raíz es cognada del hebreo שָׂהֵד y está emparentada con amplio vocabulario semítico sobre testimonio y atestiguación (siríaco, árabe shahida). La palabra figura en el famoso juego de palabras bilingüe donde el montón de piedras sirve como ''testigo'' entre Jacob y Labán, conmemorando su alianza. Documentos arameos de Egipto emplean formas relacionadas para testigos en contextos legales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3027', 'spa', 'Mano; por extensión: lado, poder, porción, medio; también espiga (ensamblaje) y asa/brazo de trono.', 'El hebreo יָד es mucho más que una parte del cuerpo. Con más de 1.600 apariciones, es uno de los sustantivos con mayor carga teológica e idiomática de las Escrituras. Designa la mano literal que agarra, golpea y bendice, pero se extiende metafóricamente al poder (''la mano del SEÑOR estaba sobre él''), la agencia (''por mano de Moisés''), la ubicación espacial (''al lado de'') y la capacidad proporcional (''conforme a la mano del rey''). Usos técnicos en Éxodo describen las espigas que unen las tablas del tabernáculo, mientras que el trono de Salomón tenía brazos — ambos llamados יָד.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3028', 'spa', 'mano — la mano fisica, y por extension poder, posesion o agencia (arameo). Yad en arameo biblico corresponde exactamente a su cognado hebreo mucho mas', 'mano — la mano fisica, y por extension poder, posesion o agencia (arameo). Yad en arameo biblico corresponde exactamente a su cognado hebreo mucho mas frecuente, designando la mano humana y sus extensiones metaforicas. Limitado a Daniel y Esdras, sus 17 apariciones abarcan un rango semantico compacto pero vivido. La aparicion mas dramatica es la mano incorporea que escribe en la pared durante el banquete de Belsasar — ''aparecieron los dedos de una mano humana y escribieron'' (Dan 5:5, 24), donde yad transmite una materialidad casi sobrenatural. La forma dual bidayin (''con manos'') aparece en la vision de la piedra ''cortada sin manos'' (Dan 2:34, 45), una frase teologicamente cargada que indica agencia divina en lugar de humana. Los usos preposicionales expresan posesion (''en tu mano,'' Esd 7:14, 25) y autoridad (''en su mano,'' Esd 5:12; Dan 2:38; 3:15, 17; 7:25). El poder de Dios se expresa con la misma palabra: ''nadie puede detener su mano'' (Dan 4:32), y el Dios de Daniel libra del poder del leon (Dan 6:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3032', 'spa', 'Echar suertes (lanzando o sacando), asignar por medio de sorteo o adivinación', 'Este verbo aparece solo tres veces en la Biblia hebrea y siempre describe el acto de echar suertes. En Joel 3:3, Abdías 11 y Nahúm 3:10, la palabra retrata a enemigos repartiendo botín o cautivos mediante la antigua práctica del sorteo, una forma de adivinación para tomar decisiones o distribuir recursos. La evidencia multilingüe confirma la acción física de lanzar, lo cual sugiere que esta forma hebrea captura específicamente el gesto de arrojar suertes para determinar resultados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3034', 'spa', 'Dar gracias, alabar o confesar (Hifil/Hitpael); originalmente ''arrojar, lanzar'' (Piel); el gesto nuclear de declarar públicamente lo que Dios ha hecho', 'Uno de los verbos teológicamente más ricos del Salterio, יָדָה en Hifil significa dar gracias o alabar, no como sentimiento privado sino como declaración pública. El Hitpael reflexivo desplaza el foco hacia dentro: confesar los propios pecados ante Dios (Lv 16:21; Neh 9:2). Debajo de ambos usos litúrgicos late un significado físico más antiguo conservado en el Piel: arrojar o derribar (Lm 3:53). Las inscripciones palmirenas confirman la acepción de acción de gracias con מודא, en paralelo al griego εὐχαριστέω, mientras que el etiópico retiene el sentido de lanzar. El cuadro completo exige tanto la alabanza exterior como la confesión interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3035', 'spa', 'Ido/Yadai, nombre propio de dos individuos (jefe manasita y hombre con esposa extranjera)', 'Nombre propio hebreo que aparece en textos bíblicos tardíos y designa a dos personas distintas: un jefe de la tribu de Manasés mencionado en 1 Crónicas 27:21, y uno de los que tomaron esposas extranjeras según Esdras 10:43, con variantes textuales entre el Ketiv y el Qeré. Las versiones griegas de la Septuaginta (Ιαδδαι, Ιαδει, Ιαδιαι) y el paralelo palmireno sugieren que el nombre podría significar «amado» o «escogido». La confusión en algunas traducciones, que lo interpretan como «su mano», evidencia las dificultades escribales con este nombre poco frecuente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3037', 'spa', 'Jadúa, nombre propio (jefe del pueblo y sumo sacerdote en tiempos de Alejandro Magno)', 'Nombre propio de líderes destacados en la Jerusalén postexílica. Aparece en Nehemías 10:21 como un jefe del pueblo que selló el pacto, y en Nehemías 12:11, 22 como sacerdote, probablemente el sumo sacerdote durante la época de Alejandro Magno. Las versiones griegas (Ιαδδου, Ιεδδου) y la propuesta académica de leerlo como יִדּוּעַ reflejan un debate vigente sobre la forma original del nombre. Este personaje representa el puente entre los períodos persa y helenístico en la historia judía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3038', 'spa', 'Jedutun — musico levita y maestro de coro designado por David para el culto del templo. Nombre propio que designa a uno de los tres musicos principale', 'Jedutun — musico levita y maestro de coro designado por David para el culto del templo. Nombre propio que designa a uno de los tres musicos principales de David, junto con Asaf y Heman. Jedutun (tambien escrito Yedutun o Yeditun) dirigia uno de los tres coros leviticos del templo y es llamado ''el vidente del rey'' en 2 Cronicas 35:15. Su nombre aparece en los titulos de los Salmos 39, 62 y 77, indicando probablemente un estilo musical o tradicion asociada con su coro. Sus descendientes continuaron la vocacion liturgica familiar durante generaciones, formando un gremio perpetuo de cantores del templo (1 Cr 16:41-42; 25:1-6; 2 Cr 29:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3039a', 'spa', 'Amado, querido, hermoso; usado de personas apreciadas por Dios y de lugares preciados para el adorador.', 'Adjetivo poético que expresa tierno afecto y preciosidad, empleado tanto sustantiva como atributivamente. Moisés bendice a Benjamín como ''el amado de YHWH'' que habita seguro entre sus hombros (Dt 33:12). Isaías canta de ''mi amado'' usando esta palabra para el Señor como viñador (Is 5:1). El salmista exclama ''¡Cuán amables son tus moradas!'' (Sal 84:1), y el Salmo 45 se titula ''canción de amores'' usando el femenino plural como sustantivo abstracto. El abanico que va desde la devoción personal hasta el deleite estético hace de esta palabra algo singularmente cálido en la poesía hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3043', 'spa', 'Yediael — nombre propio que significa ''conocido de Dios'', usado por un guerrero benjaminita, un héroe de David y un portero coraíta.', 'Nombre personal hebreo (יְדִיעֲאֵל) que significa ''conocido de Dios'' o ''Dios conoce'', llevado por al menos tres individuos distintos en los registros del Cronista. El más prominente es un jefe de clan benjaminita cuyos descendientes se enumeran entre guerreros valientes (1 Chr 7:6–11). Otro Yediael aparece entre los soldados de élite de David (1 Chr 11:45), probablemente el mismo capitán manasita que desertó hacia David en Siclag (1 Chr 12:21). Un tercero sirve como portero coraíta del templo (1 Chr 26:2). La Septuaginta traduce el nombre de diversas formas como Ιεδιηλ y Ελθειηλ, reflejando fluidez textual en la transmisión griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3045', 'spa', 'conocer, saber, percibir; conocer carnalmente; Hifil: dar a conocer, informar; Nifal: ser conocido; Hitpael: darse a conocer', 'Verbo fundamental que abarca el conocimiento cognitivo, la relación personal y la experiencia íntima. En Qal cubre desde saber hechos y percibir la verdad hasta el conocimiento relacional de personas y el eufemismo hebreo para la unión conyugal (''conoció a su mujer''). Las formas causativas (Hifil, Piel) significan ''dar a conocer'' o ''informar''; las pasivas (Nifal, Pual) expresan ser conocido o descubierto. El Hitpael capta la autorrevelación: ''me daré a conocer.'' Esta sola raíz entrelaza percepción mental, relación personal y conocimiento corporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3046', 'spa', 'Conocer, percibir o entender; en el causativo, dar a conocer, declarar o revelar informacion a otro.', 'Conocer, percibir o entender; en el causativo, dar a conocer, declarar o revelar informacion a otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3048', 'spa', 'Jedaías (יְדַעְיָה) — ''YHWH ha conocido/considerado''; nombre sacerdotal de varias figuras postexílicas', 'El nombre propio Jedaías (יְדַעְיָה, ''YHWH ha conocido'' o ''YHWH ha considerado'') designa a varios individuos en los registros sacerdotales y postexílicos. El más destacado es el jefe de la segunda división sacerdotal (1 Cr 24:7), cuyos descendientes regresaron de Babilonia como una numerosa familia sacerdotal de 973 miembros (Esd 2:36; Neh 7:39). El nombre también aparece entre quienes se establecieron en Jerusalén tras el retorno (1 Cr 9:10; Neh 11:10), en listas de firmantes sacerdotales y participantes en la dedicación de la muralla (Neh 12:6-7, 19, 21). Zacarías 6:10, 14 menciona a un Jedaías entre los exiliados de quienes se toma oro y plata para elaborar una corona simbólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3049', 'spa', 'Espíritu familiar, adivino — quien invoca a los muertos o canaliza conocimiento oculto; siempre condenado', 'El sustantivo יִדְּעֹנִי (yiddoní) designa a un practicante de la adivinación que dice poseer conocimiento esotérico mediante contacto con el mundo espiritual. Etimológicamente vinculado a la raíz ידע (''conocer''), el término sugiere a alguien que ''sabe'' por medios sobrenaturales o prohibidos. Aparece casi invariablemente emparejado con אוֹב (''médium, nigromante''), formando una expresión fija para la consulta ocultista condenada. La ley mosaica prohíbe explícitamente recurrir a los yiddonim (Lv 19:31; 20:6, 27; Dt 18:11), y las reformas tanto de Saúl (1 S 28:3, 9) como de Josías (2 R 23:24) incluyeron su expulsión. Isaías 8:19 y 19:3 presentan tal consulta como la antítesis de buscar a YHWH.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3050', 'spa', 'Yah — forma contraída del nombre divino YHWH, usada en poesía, alabanza y la exclamación Aleluya. Yah es una contracción poética del nombre divino YHW', 'Yah — forma contraída del nombre divino YHWH, usada en poesía, alabanza y la exclamación Aleluya. Yah es una contracción poética del nombre divino YHWH (Yahveh), que aparece 48 veces casi exclusivamente en contextos elevados o litúrgicos. Surge por primera vez en el Cántico del Mar: ''mi fortaleza y mi canción es Yah'' (Éx 15:2) y reaparece en la frase arcaica ''una mano sobre el trono de Yah'' (Éx 17:16). Su contexto más célebre es el Salterio, donde ancla la exclamación hallelu-Yah (''¡Alabad a Yah!'') que abre y cierra los Salmos del Hallel y la doxología final del Salterio (Sal 113–118; 146–150). Isaías cita el Cántico del Mar (Is 12:2) y usa la forma duplicada ''en Yah YHWH'' (Is 26:4). El nombre también aparece incrustado en docenas de nombres personales teofóricos (Elías, Isaías, Zacarías), aunque esos compuestos son lemas separados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3051', 'spa', 'Dar, entregar; tambien atribuir (gloria), exhortar (''vamos!''), y raramente colocar o poner.', 'Dar, entregar; tambien atribuir (gloria), exhortar (''vamos!''), y raramente colocar o poner.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3052', 'spa', 'Dar, conceder, otorgar; en forma pasiva, ser dado; también entregar, rendir, y colocar o poner en posición', 'Dar, conceder, otorgar; en forma pasiva, ser dado; también entregar, rendir, y colocar o poner en posición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3058', 'spa', 'Jehú — principalmente el celoso rey de Israel que derrocó la casa de Acab; también un profeta y otros. El nombre יֵהוּא (Yehu, probablemente contracci', 'Jehú — principalmente el celoso rey de Israel que derrocó la casa de Acab; también un profeta y otros. El nombre יֵהוּא (Yehu, probablemente contracción de ''YHWH es Él'') lo porta de manera más prominente el décimo rey de Israel, ungido por el siervo de Eliseo para ejecutar el juicio divino contra la dinastía de Acab (2 Re 9–10). La furiosa cabalgata en carro de Jehú y la destrucción total del culto a Baal se hicieron legendarias; Oseas 1:4 revisita posteriormente ''la sangre de Jezreel'' como un acto que requiere rendición de cuentas. Un profeta llamado Jehú hijo de Hananí también aparece pronunciando juicio contra Baasa (1 Re 16:1, 7) y registrando los hechos de Josafat (2 Cr 20:34). Otros portadores incluyen uno de los guerreros de David (1 Cr 12:3) y figuras tribales en genealogías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3059', 'spa', 'Joacaz — nombre teoforico (''YHWH ha asido'') llevado por reyes de Israel y Juda. Nombre teoforico que significa ''YHWH ha asido'' o ''YHWH ha tomado,'' lle', 'Joacaz — nombre teoforico (''YHWH ha asido'') llevado por reyes de Israel y Juda. Nombre teoforico que significa ''YHWH ha asido'' o ''YHWH ha tomado,'' llevado por varias figuras reales. Los mas prominentes son Joacaz hijo de Jehu, rey de Israel, cuyo reinado estuvo marcado por la opresion aramea (2 Re 13:1-9, 22, 25), y Joacaz hijo de Josias, rey de Juda, quien reino solo tres meses antes de que el faraon Necao lo depusiera (2 Re 23:30-34). Una forma variante Joacaz (יוֹאָחָז) aparece para algunos de los mismos individuos. El nombre es esencialmente una forma invertida de Ococias (אֲחַזְיָה), ambos construidos con la misma raiz אחז y el nombre divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3060', 'spa', 'Joas / Yehoash — nombre real teoforico llevado por reyes de Juda e Israel y otras figuras biblicas. Yehoash (tambien contraido como Yoash) es un nombr', 'Joas / Yehoash — nombre real teoforico llevado por reyes de Juda e Israel y otras figuras biblicas. Yehoash (tambien contraido como Yoash) es un nombre propio teoforico que significa ''YHWH es fuerte'' o ''YHWH ha otorgado,'' llevado de manera mas prominente por dos reyes de la monarquia dividida. Joas de Juda, hijo de Ococias, fue rescatado de bebe de la masacre de la reina Atalia y escondido en el templo durante seis anos antes de ser coronado en el dramatico golpe del sacerdote Joiada (2 Re 11:2-21; 2 Cr 22:11-24:27). Reparo el templo pero termino mal, asesinado por sus propios siervos despues de apartarse de Dios. Joas de Israel, hijo de Joacaz, visito al moribundo Eliseo y se le dijo que golpeara el suelo con flechas; sus tibios tres golpes le ganaron solo tres victorias sobre Aram en lugar de una derrota total (2 Re 13:10-25). Tambien derroto a Amasias de Juda, abriendo brecha en los muros de Jerusalen (2 Re 14:8-16; 2 Cr 25:17-25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3061', 'spa', 'Yehud, forma aramea de ''Judá'' usada en textos postexílicos (Esdras, Daniel) para la provincia o el pueblo', 'Yehud (יְהוּד) es el equivalente arameo del hebreo Yehudá (Judá) y aparece exclusivamente en las secciones arameas de Esdras y Daniel. Designa tanto la provincia persa de Judá como al pueblo judío en cuanto identidad étnico-territorial. En Daniel, la expresión ''hijos del cautiverio de Yehud'' (Dn 2:25; 5:13; 6:14) marca la identidad de Daniel, mientras que en Esdras nombra la provincia donde se lleva a cabo la reconstrucción del templo (Esd 5:1, 8; 7:14). El paso del hebreo Yehudá al arameo Yehud refleja la realidad lingüística de los períodos exílico y postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3062', 'spa', 'Judío, judeano — sustantivo gentilicio arameo para los miembros de la provincia de Judá en el período persa', 'El sustantivo arameo יְהוּדָאי (yehudaí) designa a un judeano o judío, y se emplea exclusivamente en las secciones arameas de Esdras. Aparece en la correspondencia entre funcionarios persas y los exiliados que retornaron, identificando a la comunidad que reconstruía Jerusalén y el templo. Los adversarios informan que ''los judíos que subieron de ti'' están reconstruyendo la ciudad (Esd 4:12, 23), mientras que los decretos persas reconocen a ''los judíos'' y sus ancianos como agentes legítimos de la reconstrucción (Esd 5:1, 5; 6:7-8, 14). El término posee fuerza tanto étnica como administrativa, identificando a la comunidad como grupo reconocible dentro del sistema provincial persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3063', 'spa', 'Judá — el patriarca, la tribu descendiente de él o el reino del sur que lleva su nombre', 'Yehudá es uno de los nombres con mayor estratificación histórica en las Escrituras. Cuando Lea declaró ''esta vez alabaré al SEÑOR'' (Gn 29:35), el nombre quedó vinculado a la acción de gracias. De aquel cuarto hijo de Jacob surgió toda una tribu y, con el tiempo, el reino del sur que sobrevivió a su contraparte septentrional. El nombre aparece 819 veces en la Biblia hebrea, abarcando narraciones patriarcales, reparticiones tribales, crónicas reales y oráculos proféticos. Interlingüísticamente, el nombre es notablemente estable, reflejando su condición de nombre propio irreductible anclado en la historia de la alianza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3064', 'spa', 'Judío, persona judía; adjetivo gentilicio y sustantivo que designa a un miembro del pueblo de Judá. Derivado del nombre tribal y territorial Judá, est', 'Judío, persona judía; adjetivo gentilicio y sustantivo que designa a un miembro del pueblo de Judá. Derivado del nombre tribal y territorial Judá, este término gentilicio identifica a una persona como perteneciente al pueblo judío. En los textos más antiguos distingue a los judahítas de otros israelitas, pero para el período persa —especialmente en Ester y Nehemías— funciona como la etiqueta étnica y comunitaria principal de la comunidad postexílica. Zacarías 8:23 vislumbra naciones aferrándose al manto de un solo hombre judío, mientras que Ester emplea el término más de sesenta veces cuando el pueblo enfrenta amenaza existencial y liberación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3065', 'spa', 'Jehudí, un oficial de la corte del rey Joacim que leyó en voz alta el rollo de Jeremías.', 'Nombre propio perteneciente a un funcionario de la corte del rey Joacim, que aparece únicamente en Jeremías 36. Jehudí fue enviado a buscar el rollo con las profecías de Jeremías y luego lo leyó en voz alta ante el rey (Jer 36:14, 21, 23). El BDB señala que el nombre pudo haber sido originalmente un apelativo que significaba ''el judío'' o ''el judeano'', lo que posiblemente indicaría ascendencia no israelita, un detalle irónico dado su papel como lector del juicio divino contra Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3066', 'spa', 'Yehudit — ''en lengua judía'', uso adverbial del adjetivo gentilicio referido al dialecto hebreo de Judá.', 'Aunque gramaticalmente es un adjetivo gentilicio femenino derivado de Yehudá (Judá), esta palabra funciona adverbialmente en todas sus apariciones bíblicas con el sentido de ''en lengua judía'', es decir, en hebreo tal como se hablaba en el reino de Judá. Aparece en el célebre intercambio diplomático durante el asedio asirio de Jerusalén, cuando los funcionarios judíos suplican al Rabsacés que no hable ''yehudit'' al alcance del oído del pueblo sobre la muralla (2 Kgs 18:26, 28; Isa 36:11, 13). Reaparece en Nehemiah 13:24 lamentando que los hijos de matrimonios mixtos ya no sabían hablar en judío. Las traducciones españolas ''en judaico'' y ''en judío'' captan bien la fuerza adverbial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3068', 'spa', 'Yahvé -- el nombre personal y pactal del Dios de Israel, el Tetragrámaton YHWH', 'El Tetragrámaton (YHWH), vocalizado como Yahvé, es el nombre sagrado y pactal mediante el cual Dios se reveló a Moisés en la zarza ardiente (Éxodo 3:14-15) y por el cual se vinculó a Israel en una relación de pacto. Con más de 6.500 apariciones es, por amplio margen, el nombre propio más frecuente en la Biblia hebrea. La reverencia judía antigua lo convirtió en un nomen ineffabile, leído en voz alta como Adonai (''mi Señor''), práctica reflejada en el Kyrios de la Septuaginta y en traducciones como el francés l''Éternel y el alemán HERR. El nombre evoca auto-existencia y fidelidad: ''YO SOY EL QUE SOY''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3069', 'spa', 'YHWH -- el sagrado Tetragrama, el nombre propio y pactual del Dios de Israel', 'Esta entrada cubre la forma vocalizada Yehovih (יֱהוִֹה), la vocalización variante del Tetragrama que se emplea cuando aparece junto a Adonay, para evitar que el lector diga «Adonay» dos veces. Las 306 ocurrencias de este grupo proceden en gran medida de la frase «Adonay YHWH» («Senor DIOS»), prominente en Ezequiel y los profetas. El nombre se enraiza en el verbo h-y-h (''ser''), evocando la autorrevelacion divina de Exodo 3:14. El frances «l''Eternel», el aleman «HERR» y el espanol «Yahve» adoptan estrategias distintas para verter este nombre inefable, reflejo de siglos de tradicion reverente en torno a su pronunciacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3075', 'spa', 'Jehozabad, nombre que significa ''Yahvé ha otorgado'', llevado por varios hombres, incluido un regicida y levitas.', 'Nombre teofórico que significa ''Yahvé ha otorgado'', portado por múltiples individuos a lo largo de los libros históricos. El más prominente es el siervo que participó en el asesinato del rey Joás de Judá (2 Re 12:21; 2 Cr 24:26). Otros portadores incluyen un comandante militar benjaminita bajo Josafat (2 Cr 17:18) y un portero levítico descendiente de Obed-edom (1 Cr 26:4). La forma abreviada Jozabad aparece para algunos de estos mismos individuos o personas emparentadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3076', 'spa', 'Yehojanán (יְהוֹחָנָן) — ''YHWH es clemente''; nombre común de figuras militares, sacerdotales y laicas', 'El nombre teofórico Yehojanán (יְהוֹחָנָן, ''YHWH es clemente'') es la forma completa detrás del posterior ''Johanán'' y el griego ''Ioannes'' (Juan). Aparece en diversos períodos y funciones: un guerrero benjamita que se unió a David en Siclag (1 Cr 12:5), un portero del templo (1 Cr 26:3), un comandante militar bajo Josafat (2 Cr 17:15), un líder sacerdotal en tiempos del sumo sacerdote Joiacim (Neh 12:13) y un laico que había tomado esposa extranjera durante las reformas de Esdras (Esd 10:28). La frecuencia de este nombre refleja su popularidad teológica: la confesión de que YHWH muestra gracia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3077', 'spa', 'Joiada — ''el SEÑOR conoce,'' el sumo sacerdote que restauró la línea davídica y padre de Benaía, guerrero de David. Yehoyada (''el SEÑOR conoce'') se des', 'Joiada — ''el SEÑOR conoce,'' el sumo sacerdote que restauró la línea davídica y padre de Benaía, guerrero de David. Yehoyada (''el SEÑOR conoce'') se destaca por encima de todos como el sumo sacerdote que derrocó a la reina Atalía y coronó al niño Joás como legítimo rey de Judá (2 Re 11–12; 2 Cr 23–24). Sus 51 apariciones se agrupan en torno a dos portadores: este sacerdote en Jerusalén y el padre del guerrero de David, Benaía (2 Sam 8:18; 23:20). La fórmula ''Benaía hijo de Joiada'' se repite con tanta frecuencia que funciona casi como un nombre compuesto. El Cronista menciona otro Joiada (1 Cr 27:34), y Jeremías menciona a un sacerdote posterior del mismo nombre (Jer 29:26).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3078', 'spa', 'Joaquín — rey de Judá exiliado a Babilonia en 597 a.C.; también llamado Conías y Jeconías', 'El nombre יְהוֹיָכִין (Yehoyakhín), que significa ''YHWH establece'', designa al penúltimo rey de Judá, quien reinó solo tres meses antes de ser deportado a Babilonia por Nabucodonosor en 597 a.C. (2 R 24:6-15). También se le conoce como Conías (Jer 22:24, 28) y Jeconías (Jer 24:1; 1 Cr 3:16-17). El capítulo final de 2 Reyes registra su notable liberación de prisión por Evil-merodac en el año trigésimo séptimo de su exilio, cuando recibió un lugar de honor a la mesa del rey babilónico (2 R 25:27-30), una conclusión que preserva un frágil hilo de esperanza davídica. Las tablillas de raciones babilónicas confirman de manera independiente su cautiverio y aprovisionamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3079', 'spa', 'Joacim — nombre teoforico que significa ''Yah levanta'', llevado por el penultimo rey de Juda y otros dos personajes.', 'Joacim — nombre teoforico que significa ''Yah levanta'', llevado por el penultimo rey de Juda y otros dos personajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3082', 'spa', 'Jonadab/Yehonadab (''YHWH es generoso''), nombre de un líder recabita y de un sobrino de David.', 'Nombre propio teofórico que significa ''YHWH es generoso'' o ''YHWH es noble'', y que aparece en dos formas alternas: la completa Yehonadav y la abreviada Yonadav. Uno de sus portadores es el hijo de Recab, el austero líder recabita que acompañó a Jehú como testigo de la purga del culto a Baal (2 R 10:15, 23) y cuyos descendientes Jeremías presentó como modelo de fidelidad (Jer 35:6-19). El otro es el astuto sobrino de David que ideó la estratagema con la que Amnón atrajo a Tamar (2 Sam 13:3-5). Dos personajes de carácter opuesto, unidos solamente por el nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H3083', 'spa', 'Jonatán, ''YHWH ha dado''; nombre propio portado por varias figuras bíblicas, principalmente el hijo de Saúl. El nombre Jonatán (Yehonatan o su forma ab', 'Jonatán, ''YHWH ha dado''; nombre propio portado por varias figuras bíblicas, principalmente el hijo de Saúl. El nombre Jonatán (Yehonatan o su forma abreviada Yonatan) significa ''YHWH ha dado,'' construido a partir del nombre divino y el verbo natan, ''dar.'' Su portador más prominente es el hijo del rey Saúl, cuya profunda amistad pactual con David y lealtad desinteresada lo han convertido en sinónimo de compañerismo fiel (1 Sam 18:1–4; 2 Sam 1:26). Otros Jonatanes notables incluyen al hijo del sacerdote Abiatar que sirvió como mensajero durante la revuelta de Absalón (2 Sam 15:27) y al sobrino de David que mató a un gigante filisteo (2 Sam 21:21).');